                    </div>

                    <div>
                      <label className="mb-2 block text-sm font-medium">Remarks</label>
                      <Textarea
                        value={remarks}
                        onChange={(e) => setRemarks(e.target.value)}
                        className="min-h-[100px] rounded-2xl"
                        placeholder="Additional remarks"
                      />
                    </div>

                    <div className="rounded-[1rem] border border-white/10 bg-card/[0.03] p-3">
                      <label className="mb-2 block text-sm font-medium">
                        Result Attachment
                      </label>
                      <input
                        type="file"
                        accept="application/pdf,image/*"
                        onChange={handleAttachmentUpload}
                        className="block w-full text-sm file:mr-4 file:rounded-xl file:border-0 file:bg-cyan-600 file:px-4 file:py-2 file:text-sm file:font-semibold file:text-white hover:file:bg-cyan-700"
                      />
                      <div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                        <FileUp className="h-4 w-4" />
                        Images are compressed before saving. PDFs are accepted up to 3MB.
                      </div>
                      {attachmentBusy ? (
                        <p className="mt-2 text-xs text-cyan-300">
                          Preparing compact file...
                        </p>
                      ) : attachment ? (
                        <div className="mt-3 flex items-center justify-between gap-3 rounded-xl border border-cyan-400/20 bg-cyan-500/10 px-3 py-2 text-sm">
                          <span className="truncate">
                            {attachment.attachmentFileName}
                          </span>
                          <Button
                            type="button"
                            size="sm"
                            variant="ghost"
                            className="rounded-xl"
                            onClick={() => setAttachment(null)}
                          >
                            Remove
                          </Button>
                        </div>
                      ) : null}
                    </div>

                    <Button
                      type="button"
                      className="h-12 rounded-2xl"
                      onClick={handleSaveResult}
                      disabled={createLabResultMutation.isPending}
                    >
                      {createLabResultMutation.isPending ? (
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      ) : (
                        <FlaskConical className="mr-2 h-4 w-4" />
                      )}
                      Save Result
                    </Button>
                  </div>
                )}

              </>
            )}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Bot,
  FileSignature,
  Loader2,
  Printer,
  Sparkles,
} from "lucide-react";
import { useCreateClinicalAiDraft } from "@/hooks/use-ai-assistant";
import { useFacilities } from "@/hooks/use-facilities";
import { usePatients } from "@/hooks/use-patients";
import { useScope } from "@/providers/scope-provider";
import { useAuth } from "@/providers/auth-provider";
import { QrCodeImage } from "@/components/shared/qr-code-image";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";

function todayDate() {
  return new Date().toISOString().slice(0, 10);
}

function displayDate(value: string) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return new Date().toLocaleDateString();
  return date.toLocaleDateString("en-KE", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

export default function MedicalRecordsPage() {
  const { user } = useAuth();
  const { facilityId, facilityName, selectedBranchName } = useScope();
  const { data: facilitiesData = [] } = useFacilities();
  const { data: patientsData = [] } = usePatients();
  const aiMutation = useCreateClinicalAiDraft();

  const facility = Array.isArray(facilitiesData)
    ? facilitiesData.find((item) => item.id === facilityId)
    : undefined;

  const [reportTitle, setReportTitle] = React.useState("Medical Report");
  const [documentType, setDocumentType] = React.useState<
    "medical" | "discharge"
  >("medical");
  const [patientSearch, setPatientSearch] = React.useState("");
  const [selectedPatientId, setSelectedPatientId] = React.useState("");
  const [patientName, setPatientName] = React.useState("");
  const [patientNumber, setPatientNumber] = React.useState("");
  const [reportDate, setReportDate] = React.useState(todayDate());
  const [clinicalNotes, setClinicalNotes] = React.useState("");
  const [impression, setImpression] = React.useState("");
  const [recommendation, setRecommendation] = React.useState("");
  const [aiInstruction, setAiInstruction] = React.useState(
    "Format these notes into a clear hospital medical report without adding undocumented facts.",
  );
  const [signatureName, setSignatureName] = React.useState(
    user?.fullName || user?.username || "",
  );
  const [designation, setDesignation] = React.useState("");
  const [signatureDataUrl, setSignatureDataUrl] = React.useState("");
  const [message, setMessage] = React.useState<string | null>(null);
  const patients = Array.isArray(patientsData) ? patientsData : [];
  const filteredPatients = React.useMemo(() => {
    const query = patientSearch.trim().toLowerCase();
    if (!query) return patients.slice(0, 80);

    return patients
      .filter((patient) =>
        [
          patient.patientNumber,
          patient.firstName,
          patient.middleName,
          patient.lastName,
          patient.phonePrimary,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(query),
      )
      .slice(0, 80);
  }, [patientSearch, patients]);

  React.useEffect(() => {
    const patient = patients.find((item) => String(item.id) === selectedPatientId);
    if (!patient) return;

    setPatientName(
      [patient.firstName, patient.middleName, patient.lastName]
        .filter(Boolean)
        .join(" "),
    );
    setPatientNumber(patient.patientNumber || "");
  }, [patients, selectedPatientId]);

  const qrPayload = JSON.stringify({
    type: documentType === "discharge" ? "discharge-summary" : "medical-report",
    title: reportTitle,
    facility: facility?.name || facilityName,
    patient: { name: patientName, number: patientNumber },
    date: reportDate,
    clinicalNotes,
    impression,
    recommendation,
    signedBy: signatureName,
  });

  const handleSignatureUpload = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      setSignatureDataUrl(String(reader.result || ""));
    };
    reader.readAsDataURL(file);
  };

