// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function patientFullName(p: PatientItem) {
  return [p.firstName, p.middleName, p.lastName].filter(Boolean).join(" ");
}

function formatDate(iso?: string | null) {
  if (!iso) return "ΓÇö";
  return new Date(iso).toLocaleDateString("en-KE", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function formatRelativeTime(iso?: string | null) {
  if (!iso) return "";
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60_000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  return `${Math.floor(hrs / 24)}d ago`;
}

// ΓöÇΓöÇΓöÇ Sub-components ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function StatPill({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-2xl border border-white/10 bg-white/[0.03] px-4 py-3">
      <p className="text-[11px] uppercase tracking-widest text-muted-foreground">{label}</p>
      <p className="mt-1 truncate text-sm font-semibold">{value}</p>
    </div>
  );
}

function EligibilityStatusBadge({ status }: { status?: string | null }) {
  if (!status) return null;
  const map: Record<string, { label: string; class: string }> = {
    ELIGIBLE: { label: "SHA Eligible", class: "bg-emerald-500/15 text-emerald-400 border-emerald-500/30" },
    NOT_ELIGIBLE: { label: "Not Eligible", class: "bg-red-500/15 text-red-400 border-red-500/30" },
    NOT_FOUND: { label: "Not Found", class: "bg-amber-500/15 text-amber-400 border-amber-500/30" },
    ACTIVE: { label: "Active", class: "bg-emerald-500/15 text-emerald-400 border-emerald-500/30" },
    INACTIVE: { label: "Inactive", class: "bg-red-500/15 text-red-400 border-red-500/30" },
  };
  const cfg = map[status] ?? { label: status, class: "bg-muted/20 text-muted-foreground border-border" };
  return (
    <span className={cn("inline-flex items-center gap-1 rounded-full border px-2.5 py-0.5 text-[11px] font-semibold", cfg.class)}>
      {cfg.label}
    </span>
  );
}

// ΓöÇΓöÇΓöÇ SHA Eligibility Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function ShaEligibilityPanel({
  prefilledMemberNumber,
  onAttach,
}: {
  prefilledMemberNumber?: string;
  onAttach?: (result: EligibilityResult) => void;
}) {
  const [identifierType, setIdentifierType] = React.useState<"member" | "nationalId">("member");
  const [memberNumber, setMemberNumber] = React.useState(prefilledMemberNumber ?? "");
  const [nationalId, setNationalId] = React.useState("");
  const [serviceDate] = React.useState(new Date().toISOString().split("T")[0]);

  const eligibilityMutation = useCheckShaEligibility();
  const result = eligibilityMutation.data;

  const handleVerify = () => {
    if (identifierType === "member" && memberNumber.trim()) {
      eligibilityMutation.mutate({ memberNumber: memberNumber.trim(), serviceDate });
    } else if (identifierType === "nationalId" && nationalId.trim()) {
      eligibilityMutation.mutate({ nationalId: nationalId.trim(), serviceDate });
    }
  };

  const statusConfig = React.useMemo(() => {
    if (!result) return null;
    if (result.status === "ELIGIBLE") return {
      icon: <ShieldCheck className="h-5 w-5 text-emerald-400" />,
      color: "border-emerald-500/30 bg-emerald-500/8",
      headerColor: "text-emerald-400",
      label: "Eligible",
    };
    if (result.status === "NOT_ELIGIBLE") return {
      icon: <ShieldAlert className="h-5 w-5 text-red-400" />,
      color: "border-red-500/30 bg-red-500/8",
      headerColor: "text-red-400",
      label: "Not Eligible",
    };
    if (result.status === "NOT_FOUND") return {
      icon: <AlertCircle className="h-5 w-5 text-amber-400" />,
      color: "border-amber-500/30 bg-amber-500/8",
      headerColor: "text-amber-400",
      label: "Not Found",
    };
    return {
      icon: <AlertCircle className="h-5 w-5 text-red-400" />,
      color: "border-red-500/30 bg-red-500/8",
      headerColor: "text-red-400",
      label: "Error",
    };
  }, [result]);

  return (
    <div className="space-y-4">
      {/* Identifier Type Toggle */}
      <div className="flex rounded-2xl border border-white/10 bg-white/[0.03] p-1">
        {[
          { id: "member" as const, label: "SHA / Member No." },
          { id: "nationalId" as const, label: "National ID" },
        ].map((tab) => (
          <button
            key={tab.id}
            type="button"
            onClick={() => setIdentifierType(tab.id)}
            className={cn(
              "flex-1 rounded-xl px-4 py-2 text-sm font-medium transition-all duration-200",
              identifierType === tab.id
                ? "bg-primary text-primary-foreground shadow-md"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Input */}
      <div className="relative">
        <Shield className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        {identifierType === "member" ? (
          <Input
            value={memberNumber}
            onChange={(e) => setMemberNumber(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleVerify()}
            placeholder="e.g. SHA-12345678 or member number"
            className="h-12 rounded-2xl pl-10 font-mono text-sm"
          />
        ) : (
          <Input
            value={nationalId}
            onChange={(e) => setNationalId(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleVerify()}
            placeholder="e.g. 12345678"
            className="h-12 rounded-2xl pl-10 font-mono text-sm"
          />
        )}
      </div>

      <Button
        type="button"
        onClick={handleVerify}
        disabled={
          eligibilityMutation.isPending ||
          (identifierType === "member" ? !memberNumber.trim() : !nationalId.trim())
        }
        className="h-11 w-full rounded-2xl gap-2"
      >
        {eligibilityMutation.isPending ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : (
          <Search className="h-4 w-4" />
        )}
        {eligibilityMutation.isPending ? "Verifying with DHAΓÇª" : "Verify SHA Eligibility"}
      </Button>

      {/* Error */}
      {eligibilityMutation.isError && (
        <div className="flex items-start gap-3 rounded-2xl border border-red-500/30 bg-red-500/8 p-4">
          <XCircle className="mt-0.5 h-4 w-4 shrink-0 text-red-400" />
          <p className="text-sm text-red-300">
            {eligibilityMutation.error?.message ?? "Verification failed. Check DHA connection."}
          </p>
        </div>
      )}

      {/* Result */}
      {result && statusConfig && (
        <div className={cn("rounded-2xl border p-5 space-y-4", statusConfig.color)}>
          {/* Header */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              {statusConfig.icon}
              <span className={cn("font-bold text-base", statusConfig.headerColor)}>
                {result.memberName ?? "ΓÇö"} ΓÇö {statusConfig.label}
              </span>
            </div>
            <EligibilityStatusBadge status={result.status} />
          </div>

          {/* Core info grid */}
          <div className="grid gap-3 sm:grid-cols-2">
            <div className="rounded-xl border border-white/8 bg-black/10 p-3">
              <p className="text-[11px] uppercase tracking-widest text-muted-foreground">Member Number</p>
              <p className="mt-1 font-mono text-sm font-semibold">{result.memberNumber ?? "ΓÇö"}</p>
            </div>
            <div className="rounded-xl border border-white/8 bg-black/10 p-3">
              <p className="text-[11px] uppercase tracking-widest text-muted-foreground">Scheme</p>
              <p className="mt-1 text-sm font-semibold">{result.scheme ?? "ΓÇö"}</p>
            </div>
            <div className="rounded-xl border border-white/8 bg-black/10 p-3">
              <p className="text-[11px] uppercase tracking-widest text-muted-foreground">Membership Status</p>
              <div className="mt-1">
                <EligibilityStatusBadge status={result.membershipStatus} />
              </div>
            </div>
            <div className="rounded-xl border border-white/8 bg-black/10 p-3">
              <p className="text-[11px] uppercase tracking-widest text-muted-foreground">Coverage</p>
              <p className="mt-1 text-sm font-semibold">
                {result.coverageStart && result.coverageEnd
                  ? `${formatDate(result.coverageStart)} ΓåÆ ${formatDate(result.coverageEnd)}`
                  : "ΓÇö"}
              </p>
            </div>
          </div>

          {/* Dependants */}
          {result.dependants && result.dependants.length > 0 && (
            <div>
              <p className="mb-2 text-[11px] uppercase tracking-widest text-muted-foreground">
                Dependants ({result.dependants.length})
              </p>
              <div className="space-y-2">
                {result.dependants.map((dep, i) => (
                  <div
                    key={i}
                    className="flex items-center justify-between rounded-xl border border-white/8 bg-black/10 px-3 py-2 text-sm"
                  >
                    <span className="font-medium">{dep.name}</span>
                    <span className="text-muted-foreground">{dep.relationship}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Benefits */}
          {result.benefits && result.benefits.length > 0 && (
            <div>
              <p className="mb-2 text-[11px] uppercase tracking-widest text-muted-foreground">Benefits</p>
              <div className="space-y-2">
                {result.benefits.slice(0, 5).map((b, i) => (
                  <div
                    key={i}
                    className="flex items-center justify-between rounded-xl border border-white/8 bg-black/10 px-3 py-2 text-sm"
                  >
                    <span className="font-medium">{b.category}</span>
                    {b.balance != null && (
                      <span className="font-mono text-xs text-muted-foreground">
                        Balance: KES {b.balance.toLocaleString()}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Timestamp + External Ref */}
          <div className="flex items-center justify-between text-[11px] text-muted-foreground border-t border-white/8 pt-3">
            <span className="flex items-center gap-1">
              <Clock className="h-3 w-3" />
              {result.responseTimestamp
                ? `Response: ${new Date(result.responseTimestamp).toLocaleTimeString("en-KE")}`
                : "Response received"}
            </span>
            {result.externalRef && (
              <span className="font-mono">Ref: {result.externalRef}</span>
            )}
          </div>

          {/* Attach to visit action */}
          {onAttach && result.status === "ELIGIBLE" && (
            <Button
              type="button"
              onClick={() => onAttach(result)}
              className="w-full h-10 rounded-xl gap-2 bg-emerald-600 hover:bg-emerald-700 text-white"
            >
              <BadgeCheck className="h-4 w-4" />
              Attach Verified Member to Visit
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

// ΓöÇΓöÇΓöÇ Main Page ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export default function PatientsPage() {
  const { data, isLoading } = usePatients();
  const { facilityId, facilityName, selectedBranchId, selectedBranchName } = useScope();

  const createPatientMutation = useCreatePatient();
  const createTriageMutation = useCreateTriage();

  const patients = Array.isArray(data) ? (data as PatientItem[]) : [];

  // ΓöÇΓöÇ Search & selection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [search, setSearch] = React.useState("");
  const [selectedPatientId, setSelectedPatientId] = React.useState<number | null>(null);

  // ΓöÇΓöÇ Visit details ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [chiefComplaint, setChiefComplaint] = React.useState("");
  const [arrivalType, setArrivalType] = React.useState("WALK_IN");
  const [triagePriority, setTriagePriority] = React.useState("NORMAL");
  const [triageNotes, setTriageNotes] = React.useState("");

  // ΓöÇΓöÇ New patient registration ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [firstName, setFirstName] = React.useState("");
  const [middleName, setMiddleName] = React.useState("");
  const [lastName, setLastName] = React.useState("");
  const [gender, setGender] = React.useState("");
  const [phonePrimary, setPhonePrimary] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [nationalId, setNationalId] = React.useState("");
  const [shaMemberNumber, setShaMemberNumber] = React.useState("");

  // ΓöÇΓöÇ SHA eligibility state attached to current visit ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [attachedEligibility, setAttachedEligibility] = React.useState<EligibilityResult | null>(null);

  // ΓöÇΓöÇ UI state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [activeTab, setActiveTab] = React.useState<"search" | "register">("search");
  const [successMessage, setSuccessMessage] = React.useState<string | null>(null);
  const [showEligibility, setShowEligibility] = React.useState(false);

  const filteredPatients = React.useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return patients.slice(0, 15);
    return patients
      .filter((p) =>
        [p.patientNumber, p.firstName, p.middleName, p.lastName, p.phonePrimary, p.email]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(q),
      )
      .slice(0, 15);
  }, [patients, search]);

  const selectedPatient = React.useMemo(
    () => patients.find((p) => p.id === selectedPatientId) ?? null,
    [patients, selectedPatientId],
  );

  // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const handleSelectPatient = (id: number) => {
    setSelectedPatientId(id);
    setAttachedEligibility(null);
    setShowEligibility(false);
  };

  const handleSendExistingToTriage = async () => {
    if (!facilityId || !selectedPatient) return;
    setSuccessMessage(null);
    const triage = await createTriageMutation.mutateAsync({
      patientId: selectedPatient.id,
      facilityId,
      branchId: selectedBranchId ?? undefined,
      arrivalType,
      chiefComplaint: chiefComplaint.trim() || "General review",
      triagePriority,
      statusCode: "WAITING_TRIAGE",
      notes: triageNotes.trim() || undefined,
    });
    setSuccessMessage(
      `Γ£ô ${patientFullName(selectedPatient)} sent to triage. Number: ${triage.triageNumber}`,
    );
    setChiefComplaint("");
    setTriageNotes("");
    setArrivalType("WALK_IN");
    setTriagePriority("NORMAL");
    setAttachedEligibility(null);
    setShowEligibility(false);
  };

  const handleRegisterAndSendToTriage = async () => {
    if (!facilityId) return;
    setSuccessMessage(null);
    const created = await createPatientMutation.mutateAsync({
      firstName: firstName.trim(),
      middleName: middleName.trim() || undefined,
      lastName: lastName.trim(),
      gender: gender.trim() || undefined,
      phonePrimary: phonePrimary.trim() || undefined,
      email: email.trim() || undefined,
      facilityId,
      isActive: true,
      isDeceased: false,
    });
    const triage = await createTriageMutation.mutateAsync({
      patientId: created.id,
      facilityId,
      branchId: selectedBranchId ?? undefined,
      arrivalType,
      chiefComplaint: chiefComplaint.trim() || "General review",
      triagePriority,
      statusCode: "WAITING_TRIAGE",
      notes: triageNotes.trim() || undefined,
    });
    setSuccessMessage(
      `Γ£ô Patient ${created.patientNumber} registered & sent to triage. No: ${triage.triageNumber}`,
    );
    setFirstName(""); setMiddleName(""); setLastName(""); setGender("");
    setPhonePrimary(""); setEmail(""); setNationalId(""); setShaMemberNumber("");
    setChiefComplaint(""); setTriageNotes("");
    setArrivalType("WALK_IN"); setTriagePriority("NORMAL");
    setAttachedEligibility(null);
  };

  const shaEligibilityIsKnown =
    selectedPatient?.shaStatus === "ELIGIBLE" || attachedEligibility?.status === "ELIGIBLE";

  return (
    <div className="space-y-6 pb-12">

      {/* ΓöÇΓöÇ Header banner ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <section className="relative overflow-hidden rounded-[2rem] border surface-spotlight shadow-md p-6 md:p-8">
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-blue-600/10 via-cyan-500/5 to-transparent" />
        <div className="pointer-events-none absolute -right-20 -top-20 h-60 w-60 rounded-full bg-cyan-400/10 blur-3xl" />
        <div className="pointer-events-none absolute -left-16 bottom-0 h-48 w-48 rounded-full bg-blue-500/10 blur-3xl" />

        <div className="relative flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
          <div className="space-y-3">
            <Badge className="rounded-full border-0 bg-primary/10 px-3 py-1 text-module">
              Reception Desk
            </Badge>
            <div className="flex items-center gap-3">
              <div className="flex h-14 w-14 items-center justify-center rounded-3xl bg-primary/10">
                <Users className="h-7 w-7 text-primary" />
              </div>
              <div>
                <h1 className="text-3xl font-bold tracking-tight md:text-4xl">
                  Reception &amp; Patient Intake
                </h1>
                <p className="text-muted-foreground mt-1">
                  Search patients ┬╖ Verify SHA eligibility ┬╖ Register new visits
                </p>
              </div>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-2 xl:w-[520px]">
            <StatPill label="Facility" value={facilityName || "No facility"} />
            <StatPill label="Branch" value={selectedBranchName || "No branch"} />
            <StatPill label="Patients on record" value={String(patients.length)} />
            <StatPill label="Search results" value={String(filteredPatients.length)} />
          </div>
        </div>
      </section>

      {/* ΓöÇΓöÇ Success banner ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {successMessage && (
        <div className="flex items-center justify-between rounded-2xl border border-emerald-500/25 bg-emerald-500/8 px-5 py-4">
          <div className="flex items-center gap-3 text-sm text-emerald-300">
            <CheckCircle2 className="h-5 w-5 shrink-0" />
            {successMessage}
          </div>
          <button
            type="button"
            onClick={() => setSuccessMessage(null)}
            className="text-muted-foreground hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* ΓöÇΓöÇ Main workspace ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="grid gap-6 xl:grid-cols-[1fr_420px]">

        {/* Left: Patient search / registration */}
        <div className="space-y-4">
          {/* Tab bar */}
          <div className="flex rounded-2xl border border-white/10 bg-white/[0.03] p-1 gap-1">
            {[
              { id: "search" as const, icon: Search, label: "Find Returning Patient" },
              { id: "register" as const, icon: UserPlus, label: "Register New Patient" },
            ].map((tab) => (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id)}
                className={cn(
                  "flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium transition-all duration-200",
                  activeTab === tab.id
                    ? "bg-primary text-primary-foreground shadow-md"
                    : "text-muted-foreground hover:text-foreground",
                )}
              >
                <tab.icon className="h-4 w-4" />
                {tab.label}
              </button>
            ))}
          </div>

          {/* ΓöÇΓöÇ Search tab ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          {activeTab === "search" && (
            <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
              <CardHeader>
                <CardTitle className="text-base">Search Returning Patient</CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="relative">
                  <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Patient number, name, or phoneΓÇª"
                    className="h-12 rounded-2xl pl-10"
                  />
                </div>

                <div className="space-y-2 max-h-[420px] overflow-y-auto pr-1">
                  {isLoading ? (
                    Array.from({ length: 5 }).map((_, i) => (
                      <div key={i} className="animate-pulse rounded-2xl border border-white/8 bg-white/[0.03] p-4">
                        <div className="h-4 w-40 rounded bg-white/10" />
                        <div className="mt-2 h-3 w-56 rounded bg-white/10" />
                      </div>
                    ))
                  ) : filteredPatients.length === 0 ? (
                    <div className="rounded-2xl border border-dashed border-white/10 bg-white/[0.02] p-6 text-center text-sm text-muted-foreground">
                      No patient found. Switch to &ldquo;Register New Patient&rdquo; to create one.
                    </div>
                  ) : (
                    filteredPatients.map((patient) => {
                      const isSelected = selectedPatientId === patient.id;
                      return (
                        <button
                          key={patient.id}
                          type="button"
                          onClick={() => handleSelectPatient(patient.id)}
                          className={cn(
                            "w-full rounded-2xl border p-4 text-left transition-all duration-200",
                            isSelected
                              ? "border-cyan-400/40 bg-cyan-500/10 shadow-sm"
                              : "border-white/10 bg-white/[0.03] hover:bg-white/[0.05]",
                          )}
                        >
                          <div className="flex items-start justify-between gap-3">
                            <div className="min-w-0 flex-1">
                              <p className="truncate font-semibold">{patientFullName(patient)}</p>
                              <p className="mt-0.5 font-mono text-xs text-muted-foreground">
                                {patient.patientNumber}
                              </p>
                              <div className="mt-1.5 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                                {patient.phonePrimary && (
                                  <span className="flex items-center gap-1">
                                    <Phone className="h-3 w-3" />
                                    {patient.phonePrimary}
                                  </span>
                                )}
                                {patient.gender && <span>{patient.gender}</span>}
                              </div>
                            </div>
                            <div className="flex flex-col items-end gap-1.5">
                              {isSelected && <CheckCircle2 className="h-4 w-4 text-cyan-400" />}
                              {patient.shaStatus && (
                                <EligibilityStatusBadge status={patient.shaStatus} />
                              )}
                              {patient.shaMemberNumber && (
                                <span className="font-mono text-[10px] text-muted-foreground">
                                  {patient.shaMemberNumber}
                                </span>
                              )}
                            </div>
                          </div>
                        </button>
                      );
                    })
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          {/* ΓöÇΓöÇ Register tab ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
          {activeTab === "register" && (
            <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
              <CardHeader>
                <CardTitle className="text-base">Register New Patient</CardTitle>
              </CardHeader>
              <CardContent className="space-y-5">
                {/* Name */}
                <div className="grid gap-4 sm:grid-cols-3">
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">First Name *</label>
                    <Input value={firstName} onChange={(e) => setFirstName(e.target.value)}
                      className="h-11 rounded-2xl" placeholder="John" />
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Middle Name</label>
                    <Input value={middleName} onChange={(e) => setMiddleName(e.target.value)}
                      className="h-11 rounded-2xl" placeholder="Optional" />
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Last Name *</label>
                    <Input value={lastName} onChange={(e) => setLastName(e.target.value)}
                      className="h-11 rounded-2xl" placeholder="Doe" />
                  </div>
                </div>

                {/* Demographics */}
                <div className="grid gap-4 sm:grid-cols-3">
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Gender</label>
                    <select
                      value={gender}
                      onChange={(e) => setGender(e.target.value)}
                      className="h-11 w-full rounded-2xl border border-input bg-background px-3 text-sm"
                    >
                      <option value="">SelectΓÇª</option>
                      <option value="MALE">Male</option>
                      <option value="FEMALE">Female</option>
                      <option value="OTHER">Other</option>
                    </select>
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Phone</label>
                    <div className="relative">
                      <Phone className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                      <Input value={phonePrimary} onChange={(e) => setPhonePrimary(e.target.value)}
                        className="h-11 rounded-2xl pl-10" placeholder="07xxxxxxxx" />
                    </div>
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Email</label>
                    <Input value={email} onChange={(e) => setEmail(e.target.value)}
                      className="h-11 rounded-2xl" placeholder="Optional" />
                  </div>
                </div>

                {/* SHA identity */}
                <div className="grid gap-4 sm:grid-cols-2">
                  <div>
                    <label className="mb-1.5 block text-sm font-medium flex items-center gap-1.5">
                      <Shield className="h-3.5 w-3.5 text-primary" /> National ID
                    </label>
                    <Input value={nationalId} onChange={(e) => setNationalId(e.target.value)}
                      className="h-11 rounded-2xl font-mono" placeholder="e.g. 12345678" />
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium flex items-center gap-1.5">
                      <CreditCard className="h-3.5 w-3.5 text-primary" /> SHA Member Number
                    </label>
                    <Input value={shaMemberNumber} onChange={(e) => setShaMemberNumber(e.target.value)}
                      className="h-11 rounded-2xl font-mono" placeholder="SHA-XXXXXXXX" />
                  </div>
                </div>

                {/* Chief complaint */}
                <div>
                  <label className="mb-1.5 block text-sm font-medium flex items-center gap-1.5">
                    <FileText className="h-3.5 w-3.5" /> Chief Complaint
                  </label>
                  <Textarea value={chiefComplaint} onChange={(e) => setChiefComplaint(e.target.value)}
                    className="min-h-[90px] rounded-2xl" placeholder="Presenting complaintΓÇª" />
                </div>

                {/* Visit params */}
                <div className="grid gap-4 sm:grid-cols-3">
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Arrival Type</label>
                    <select value={arrivalType} onChange={(e) => setArrivalType(e.target.value)}
                      className="h-11 w-full rounded-2xl border border-input bg-background px-3 text-sm">
                      <option value="WALK_IN">Walk In</option>
                      <option value="REFERRAL">Referral</option>
                      <option value="EMERGENCY">Emergency</option>
                      <option value="APPOINTMENT">Appointment</option>
                    </select>
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Priority</label>
                    <select value={triagePriority} onChange={(e) => setTriagePriority(e.target.value)}
                      className="h-11 w-full rounded-2xl border border-input bg-background px-3 text-sm">
                      <option value="NORMAL">Normal</option>
                      <option value="URGENT">Urgent</option>
                      <option value="EMERGENCY">Emergency</option>
                      <option value="LOW">Low</option>
                    </select>
                  </div>
                  <div>
                    <label className="mb-1.5 block text-sm font-medium">Branch</label>
                    <Input value={selectedBranchName || "No branch"} disabled
                      className="h-11 rounded-2xl opacity-70" />
                  </div>
                </div>

                <Button
                  type="button"
                  onClick={handleRegisterAndSendToTriage}
                  disabled={
                    !facilityId ||
                    !firstName.trim() ||
                    !lastName.trim() ||
                    createPatientMutation.isPending ||
                    createTriageMutation.isPending
                  }
                  className="h-12 w-full rounded-2xl gap-2"
                >
                  {createPatientMutation.isPending || createTriageMutation.isPending ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <UserPlus className="h-4 w-4" />
                  )}
                  Register &amp; Send to Triage
                </Button>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Right: Selected patient + SHA eligibility panel */}
        <div className="space-y-4">

          {/* Selected patient card */}
          {selectedPatient && activeTab === "search" ? (
            <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-cyan-500 to-blue-600" />
              <CardHeader>
                <CardTitle className="flex items-center justify-between text-base">
                  Selected Patient
                  {shaEligibilityIsKnown && (
                    <span className="flex items-center gap-1 text-xs font-normal text-emerald-400">
                      <ShieldCheck className="h-4 w-4" /> SHA Verified
                    </span>
                  )}
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-5">
                {/* Patient summary */}
                <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                  <p className="text-lg font-bold">{patientFullName(selectedPatient)}</p>
                  <p className="mt-0.5 font-mono text-xs text-muted-foreground">
                    {selectedPatient.patientNumber}
                  </p>
                  <div className="mt-3 grid gap-2 sm:grid-cols-2 text-sm">
                    <div>
                      <span className="text-muted-foreground">Phone: </span>
                      {selectedPatient.phonePrimary || "ΓÇö"}
                    </div>
                    <div>
                      <span className="text-muted-foreground">Gender: </span>
                      {selectedPatient.gender || "ΓÇö"}
                    </div>
                    {selectedPatient.shaMemberNumber && (
                      <div className="col-span-2">
                        <span className="text-muted-foreground">SHA No: </span>
                        <span className="font-mono">{selectedPatient.shaMemberNumber}</span>
                      </div>
                    )}
                    {selectedPatient.shaEligibilityUpdatedAt && (
                      <div className="col-span-2 text-xs text-muted-foreground">
                        Last verified {formatRelativeTime(selectedPatient.shaEligibilityUpdatedAt)}
                      </div>
                    )}
                  </div>
                </div>

                {/* SHA eligibility toggle */}
                <div>
                  <button
                    type="button"
                    onClick={() => setShowEligibility((v) => !v)}
                    className={cn(
                      "flex w-full items-center justify-between rounded-2xl border px-4 py-3 text-sm font-medium transition-all duration-200",
                      showEligibility
                        ? "border-primary/40 bg-primary/8 text-primary"
                        : "border-white/10 bg-white/[0.03] hover:bg-white/[0.05]",
                    )}
                  >
                    <span className="flex items-center gap-2">
                      <Shield className="h-4 w-4" />
                      {showEligibility ? "Hide SHA Eligibility" : "Verify SHA Eligibility"}
                    </span>
                    {attachedEligibility?.status === "ELIGIBLE" && (
                      <ShieldCheck className="h-4 w-4 text-emerald-400" />
                    )}
                  </button>
                </div>

                {showEligibility && (
                  <ShaEligibilityPanel
                    prefilledMemberNumber={selectedPatient.shaMemberNumber ?? ""}
                    onAttach={(result) => {
                      setAttachedEligibility(result);
                    }}
                  />
                )}

                {/* Visit form */}
                <div className="space-y-3 border-t border-white/10 pt-4">
                  <p className="text-sm font-medium text-muted-foreground">Visit Details</p>
                  <Textarea
                    value={chiefComplaint}
                    onChange={(e) => setChiefComplaint(e.target.value)}
                    placeholder="Chief complaint / reason for visit"
                    className="min-h-[80px] rounded-2xl"
                  />
                  <div className="grid gap-3 sm:grid-cols-2">
                    <select value={arrivalType} onChange={(e) => setArrivalType(e.target.value)}
                      className="h-11 rounded-2xl border border-input bg-background px-3 text-sm">
                      <option value="WALK_IN">Walk In</option>
                      <option value="REFERRAL">Referral</option>
                      <option value="EMERGENCY">Emergency</option>
                      <option value="APPOINTMENT">Appointment</option>
                    </select>
                    <select value={triagePriority} onChange={(e) => setTriagePriority(e.target.value)}
                      className="h-11 rounded-2xl border border-input bg-background px-3 text-sm">
                      <option value="NORMAL">Normal Priority</option>
                      <option value="URGENT">Urgent</option>
                      <option value="EMERGENCY">Emergency</option>
                      <option value="LOW">Low</option>
                    </select>
                  </div>
                  <Button
                    type="button"
                    onClick={handleSendExistingToTriage}
                    disabled={!selectedPatient || !facilityId || createTriageMutation.isPending}
                    className="h-12 w-full rounded-2xl gap-2"
                  >
                    {createTriageMutation.isPending ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Send className="h-4 w-4" />
                    )}
                    Send to Triage
                  </Button>
                </div>
              </CardContent>
            </Card>
          ) : activeTab === "search" ? (
            /* No patient selected placeholder */
            <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
              <CardContent className="flex flex-col items-center justify-center gap-4 py-16 text-center">
                <div className="flex h-16 w-16 items-center justify-center rounded-3xl bg-primary/10">
                  <Users className="h-8 w-8 text-primary" />
                </div>
                <div>
                  <p className="font-semibold">No patient selected</p>
                  <p className="mt-1 text-sm text-muted-foreground">
                    Search and click a patient to view their record and send them to triage.
                  </p>
                </div>
              </CardContent>
            </Card>
          ) : null}

          {/* Standalone eligibility check (visible when on register tab or no patient) */}
          {(activeTab === "register" || !selectedPatient) && (
            <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
              <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-emerald-500 to-teal-600" />
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-base">
                  <Shield className="h-5 w-5 text-primary" />
                  SHA Eligibility Verification
                </CardTitle>
              </CardHeader>
              <CardContent>
                <ShaEligibilityPanel
                  onAttach={(result) => {
                    setAttachedEligibility(result);
                    if (result.memberNumber) setShaMemberNumber(result.memberNumber);
                  }}
                />
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  BadgeDollarSign,
  CheckCircle2,
  Download,
  FileText,
  Loader2,
  PackagePlus,
  Pill,
  Save,
  Search,
  Upload,
  Warehouse,
} from "lucide-react";

import { useScope } from "@/providers/scope-provider";
import { useBranchPharmacyStock } from "@/hooks/use-branch-pharmacy-stock";
import { useCreateBranchMedicineStock } from "@/hooks/use-create-branch-medicine-stock";
import { useCreatePharmacyMedicine } from "@/hooks/use-create-pharmacy-medicine";
import { useImportBranchMedicinePricing } from "@/hooks/use-import-branch-medicine-pricing";
import { usePharmacyMedicines } from "@/hooks/use-pharmacy-medicines";
import { useRestockBranchMedicine } from "@/hooks/use-restock-branch-medicine";
import { useUpdateBranchMedicineStock } from "@/hooks/use-update-branch-medicine-stock";
import {
  getBranchMedicinePricingTemplate,
  type BranchMedicineStockItem,
} from "@/services/pharmacy-stock-service";
import type { PharmacyMedicine } from "@/services/pharmacy-service";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { appSelectClass } from "@/lib/select-class";

function formatMoney(value?: number | null) {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "KES",
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

function medicineLabel(medicine?: PharmacyMedicine | null) {
  if (!medicine) return "Unknown medicine";
  return [medicine.name, medicine.strength, medicine.dosageForm]
    .filter(Boolean)
    .join(" / ");
}

function numberOrUndefined(value: string) {
  const trimmed = value.trim();
  return trimmed ? Number(trimmed) : undefined;
}

export default function PharmacyPricingPage() {
  const {
    facilityId,
    facilityName,
    selectedBranchId,
    selectedBranchName,
    availableBranches,
    canSwitchBranches,
    setSelectedBranchId,
  } = useScope();

  const { data: medicinesData = [], isLoading: medicinesLoading } =
    usePharmacyMedicines();
  const { data: stockData = [], isLoading: stockLoading } =
    useBranchPharmacyStock(selectedBranchId, { pageSize: 100 });
  const createMedicineMutation = useCreatePharmacyMedicine();
  const createStockMutation = useCreateBranchMedicineStock();
  const importPricingMutation = useImportBranchMedicinePricing();
  const updateStockMutation = useUpdateBranchMedicineStock(selectedBranchId);
  const restockMutation = useRestockBranchMedicine();

  const medicines = Array.isArray(medicinesData) ? medicinesData : [];
  const branchStock = Array.isArray(stockData) ? stockData : (stockData?.data ?? []);

  const [message, setMessage] = React.useState<string | null>(null);
  const [search, setSearch] = React.useState("");
  const [medicinePickerSearch, setMedicinePickerSearch] = React.useState("");
  const [isDownloadingTemplate, setIsDownloadingTemplate] =
    React.useState(false);
  const fileInputRef = React.useRef<HTMLInputElement | null>(null);

  const [medicineCode, setMedicineCode] = React.useState("");
  const [medicineName, setMedicineName] = React.useState("");
  const [dosageForm, setDosageForm] = React.useState("");
  const [strength, setStrength] = React.useState("");
  const [manufacturer, setManufacturer] = React.useState("");
  const [defaultUnitPrice, setDefaultUnitPrice] = React.useState("");

  const [selectedMedicineId, setSelectedMedicineId] = React.useState("");
  const [initialStock, setInitialStock] = React.useState("");
  const [branchReorderLevel, setBranchReorderLevel] = React.useState("");
  const [branchBuyingPrice, setBranchBuyingPrice] = React.useState("");
  const [branchUnitPrice, setBranchUnitPrice] = React.useState("");

  const [editingStockId, setEditingStockId] = React.useState<number | null>(
    null,
  );
  const [editBuyingPrice, setEditBuyingPrice] = React.useState("");
  const [editUnitPrice, setEditUnitPrice] = React.useState("");
  const [editReorderLevel, setEditReorderLevel] = React.useState("");
  const [editStockQuantity, setEditStockQuantity] = React.useState("");
  const [reorderSearch, setReorderSearch] = React.useState("");
  const [selectedReorderStockId, setSelectedReorderStockId] = React.useState("");
  const [reorderQuantity, setReorderQuantity] = React.useState("");
  const [reorderBuyingPrice, setReorderBuyingPrice] = React.useState("");
  const [reorderUnitPrice, setReorderUnitPrice] = React.useState("");

  const stockMedicineIds = new Set(branchStock.map((item) => item.medicineId));
  const unmappedMedicines = medicines.filter(
    (medicine) => !stockMedicineIds.has(medicine.id),
  );

  const filteredUnmappedMedicines = React.useMemo(() => {
    const query = medicinePickerSearch.trim().toLowerCase();
    if (!query) return unmappedMedicines.slice(0, 120);

    return unmappedMedicines
      .filter((medicine) =>
        [
          medicine.name,
          medicine.code,
          medicine.dosageForm,
          medicine.strength,
          medicine.manufacturer,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(query),
      )
      .slice(0, 120);
  }, [medicinePickerSearch, unmappedMedicines]);

  const filteredStock = branchStock.filter((item) => {
    const query = search.trim().toLowerCase();
    if (!query) return true;

    return [
      item.medicine?.name,
      item.medicine?.code,
      item.medicine?.dosageForm,
      item.medicine?.strength,
      item.branch?.name,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase()
      .includes(query);
  });

  const filteredReorderStock = React.useMemo(() => {
    const query = reorderSearch.trim().toLowerCase();
    const source = branchStock.filter((item) => item.isActive !== false);
    if (!query) return source.slice(0, 120);

    return source
      .filter((item) =>
        [
          item.medicine?.name,
          item.medicine?.code,
          item.medicine?.dosageForm,
          item.medicine?.strength,
          item.branch?.name,
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase()
          .includes(query),
      )
      .slice(0, 120);
  }, [branchStock, reorderSearch]);

  const missingPriceCount = branchStock.filter(
    (item) => item.unitPrice <= 0,
  ).length;
  const missingBuyingCount = branchStock.filter(
    (item) => item.buyingPrice <= 0,
  ).length;
  const totalStockValue = branchStock.reduce(
    (sum, item) => sum + item.stockQuantity * item.unitPrice,
    0,
  );
  const totalCostValue = branchStock.reduce(
    (sum, item) => sum + item.stockQuantity * item.buyingPrice,
    0,
  );
  const estimatedMargin = totalStockValue - totalCostValue;
  const activeCount = branchStock.filter((item) => item.isActive).length;

  const activeEditStock =
    branchStock.find((item) => item.id === editingStockId) ?? null;
  const activeReorderStock =
    branchStock.find((item) => String(item.id) === selectedReorderStockId) ??
    null;

  React.useEffect(() => {
    if (!activeReorderStock) {
      setReorderBuyingPrice("");
      setReorderUnitPrice("");
      return;
    }

    setReorderBuyingPrice(String(activeReorderStock.buyingPrice ?? 0));
    setReorderUnitPrice(String(activeReorderStock.unitPrice ?? 0));
  }, [activeReorderStock?.id]);

  const handleCreateMedicine = async () => {
    setMessage(null);

    if (!medicineCode.trim() || !medicineName.trim()) {
      setMessage("Medicine code and name are required.");
      return;
    }

    try {
      await createMedicineMutation.mutateAsync({
        code: medicineCode.trim(),
        name: medicineName.trim(),
        dosageForm: dosageForm.trim() || undefined,
        strength: strength.trim() || undefined,
        manufacturer: manufacturer.trim() || undefined,
        unitPrice: numberOrUndefined(defaultUnitPrice),
        isActive: true,
      });

      setMedicineCode("");
      setMedicineName("");
      setDosageForm("");
      setStrength("");
      setManufacturer("");
      setDefaultUnitPrice("");
      setMessage("Medicine master item created.");
    } catch (error) {
      setMessage(
        error instanceof Error ? error.message : "Unable to create medicine.",
      );
    }
  };

  const handleCreateBranchStock = async () => {
    setMessage(null);

    if (!facilityId || !selectedBranchId) {
      setMessage("Select a facility branch before creating branch pricing.");
      return;
    }

    if (!selectedMedicineId) {
      setMessage("Select a medicine to add to this branch.");
      return;
    }

    try {
      await createStockMutation.mutateAsync({
        facilityId,
        branchId: selectedBranchId,
        medicineId: Number(selectedMedicineId),
        stockQuantity: numberOrUndefined(initialStock) ?? 0,
        reorderLevel: numberOrUndefined(branchReorderLevel) ?? 0,
        buyingPrice: numberOrUndefined(branchBuyingPrice) ?? 0,
        unitPrice: numberOrUndefined(branchUnitPrice) ?? 0,
        isActive: true,
      });

      setSelectedMedicineId("");
      setInitialStock("");
      setBranchReorderLevel("");
      setBranchBuyingPrice("");
      setBranchUnitPrice("");
      setMessage("Branch medicine price and stock created.");
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to create branch medicine price.",
      );
    }
  };

  const handleStartEdit = (stock: BranchMedicineStockItem) => {
    setEditingStockId(stock.id);
    setEditBuyingPrice(String(stock.buyingPrice ?? 0));
    setEditUnitPrice(String(stock.unitPrice ?? 0));
    setEditReorderLevel(String(stock.reorderLevel ?? 0));
    setEditStockQuantity(String(stock.stockQuantity ?? 0));
    setMessage(null);
  };

  const handleSaveEdit = async () => {
    if (!activeEditStock) return;
    setMessage(null);

    try {
      await updateStockMutation.mutateAsync({
        stockId: activeEditStock.id,
        payload: {
          buyingPrice: Number(editBuyingPrice || 0),
          unitPrice: Number(editUnitPrice || 0),
          reorderLevel: Number(editReorderLevel || 0),
          stockQuantity: Number(editStockQuantity || 0),
        },
      });

      setEditingStockId(null);
      setMessage("Branch price and stock controls updated.");
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to update branch medicine price.",
      );
    }
  };

  const handleRestock = async () => {
    setMessage(null);

    if (!activeReorderStock) {
      setMessage("Search and select the drug to reorder.");
      return;
    }

    const quantity = Number(reorderQuantity || 0);
    if (!Number.isFinite(quantity) || quantity <= 0) {
      setMessage("Enter a valid reordered quantity.");
      return;
    }

    try {
      await restockMutation.mutateAsync({
        stockId: activeReorderStock.id,
        payload: {
          quantityToAdd: quantity,
          buyingPrice: numberOrUndefined(reorderBuyingPrice),
          unitPrice: numberOrUndefined(reorderUnitPrice),
        },
      });

      setSelectedReorderStockId("");
      setReorderSearch("");
      setReorderQuantity("");
      setReorderBuyingPrice("");
      setReorderUnitPrice("");
      setMessage("Drug reorder received and branch stock updated.");
    } catch (error) {
      setMessage(
        error instanceof Error ? error.message : "Unable to update reorder.",
      );
    }
  };

  const handleDownloadTemplate = async () => {
    setMessage(null);

    if (!selectedBranchId) {
      setMessage("Select a branch before downloading the pricing template.");
      return;
    }

    try {
      setIsDownloadingTemplate(true);
      const template = await getBranchMedicinePricingTemplate(selectedBranchId);
      const blob = new Blob([`\uFEFF${template.csvText}`], {
        type: "text/csv;charset=utf-8",
      });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = template.fileName;
      link.click();
      window.URL.revokeObjectURL(url);
      setMessage(
        `Template ready for ${template.branch.name}. ${template.rowCount} master medicines included.`,
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to download branch pricing template.",
      );
    } finally {
      setIsDownloadingTemplate(false);
    }
  };

  const handleImportTemplate = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    setMessage(null);

    if (!selectedBranchId) {
      setMessage("Select a branch before importing pharmacy pricing.");
      event.target.value = "";
      return;
    }

    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const csvText = await file.text();
      const result = await importPricingMutation.mutateAsync({
        branchId: selectedBranchId,
        csvText,
      });
      setMessage(
        `Imported ${result.processed} rows: ${result.created} branch prices created, ${result.updated} updated, ${result.masterCreated ?? 0} new master drugs added, ${result.skipped} skipped.`,
      );
    } catch (error) {
      setMessage(
        error instanceof Error
          ? error.message
          : "Unable to import branch pharmacy pricing.",
      );
    } finally {
      event.target.value = "";
    }
  };

  return (
    <div className="space-y-6">
      <section className="relative overflow-hidden rounded-[1.4rem] border surface-spotlight p-6 shadow-md md:p-8">
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-emerald-500/16 via-cyan-500/8 to-transparent" />
        <div className="relative flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-3xl">
            <Badge className="mb-4 rounded-full border-0 bg-success/10 px-3 py-1 text-success">
              Medicine master and branch pricing
            </Badge>
            <div className="flex items-center gap-4">
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-background/80">
                <Pill className="h-7 w-7 text-emerald-500" />
              </div>
              <div>
                <h1 className="text-3xl font-bold tracking-tight md:text-4xl">
                  Pharmacy Pricing
                </h1>
                <p className="mt-2 text-sm text-muted-foreground">
                  Common medicine catalogue, branch-specific stock, and branch
                  selling prices wired to dispensing.
                </p>
              </div>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-2 lg:min-w-[420px]">
            <div className="rounded-xl border bg-background/70 p-4">
              <p className="text-xs uppercase text-muted-foreground">
                Facility
              </p>
              <p className="mt-2 text-sm font-semibold">
                {facilityName || "No facility"}
              </p>
            </div>
            <div className="rounded-xl border bg-background/70 p-4">
              <p className="text-xs uppercase text-muted-foreground">Branch</p>
              {canSwitchBranches ? (
                <select
                  value={selectedBranchId ? String(selectedBranchId) : ""}
                  onChange={(event) =>
                    setSelectedBranchId(
                      event.target.value
                        ? Number(event.target.value)
                        : undefined,
                    )
                  }
                  className="mt-2 h-10 w-full rounded-xl border bg-background px-3 text-sm"
                >
                  <option value="">Select branch</option>
                  {availableBranches.map((branch) => (
                    <option key={branch.id} value={String(branch.id)}>
                      {branch.name}
                    </option>
                  ))}
                </select>
              ) : (
                <p className="mt-2 text-sm font-semibold">
                  {selectedBranchName || "No branch"}
                </p>
              )}
            </div>
          </div>
        </div>
      </section>

      {message ? (
        <div className="rounded-xl border border-cyan-500/20 bg-cyan-500/10 px-4 py-3 text-sm text-module">
          {message}
        </div>
      ) : null}

      <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Medicine Master</p>
              <p className="mt-2 text-2xl font-bold">{medicines.length}</p>
            </div>
            <Pill className="h-7 w-7 text-emerald-500" />
          </CardContent>
        </Card>
        <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Branch Items</p>
              <p className="mt-2 text-2xl font-bold">{branchStock.length}</p>
              <p className="mt-1 text-xs text-muted-foreground">
                {activeCount} active
              </p>
            </div>
            <Warehouse className="h-7 w-7 text-cyan-500" />
          </CardContent>
        </Card>
        <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Stock Value</p>
              <p className="mt-2 text-xl font-bold">
                {formatMoney(totalStockValue)}
              </p>
              <p className="mt-1 text-xs text-muted-foreground">
                Margin {formatMoney(estimatedMargin)}
              </p>
            </div>
            <BadgeDollarSign className="h-7 w-7 text-amber-500" />
          </CardContent>
        </Card>
        <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Price Gaps</p>
              <p className="mt-2 text-2xl font-bold">{missingPriceCount}</p>
              <p className="mt-1 text-xs text-muted-foreground">
                {missingBuyingCount} missing buying cost
              </p>
            </div>
            <CheckCircle2 className="h-7 w-7 text-destructive" />
          </CardContent>
        </Card>
      </section>

      <section className="grid gap-5 xl:grid-cols-[0.95fr_1.05fr]">
        <div className="space-y-5">
          <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Create Medicine Master</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-medium">Code</label>
                  <Input
                    value={medicineCode}
                    onChange={(event) => setMedicineCode(event.target.value)}
                    className="h-12 rounded-xl"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">Name</label>
                  <Input
                    value={medicineName}
                    onChange={(event) => setMedicineName(event.target.value)}
                    className="h-12 rounded-xl"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Dosage Form
                  </label>
                  <Input
                    value={dosageForm}
                    onChange={(event) => setDosageForm(event.target.value)}
                    className="h-12 rounded-xl"
                    placeholder="Tablet, syrup, injection"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Strength
                  </label>
                  <Input
                    value={strength}
                    onChange={(event) => setStrength(event.target.value)}
                    className="h-12 rounded-xl"
                    placeholder="500mg, 5mg/ml"
                  />
                </div>
              </div>
              <div>
                <label className="mb-2 block text-sm font-medium">
                  Manufacturer
                </label>
                <Input
                  value={manufacturer}
                  onChange={(event) => setManufacturer(event.target.value)}
                  className="h-12 rounded-xl"
                />
              </div>
              <div>
                <label className="mb-2 block text-sm font-medium">
                  Default Price
                </label>
                <Input
                  type="number"
                  value={defaultUnitPrice}
                  onChange={(event) => setDefaultUnitPrice(event.target.value)}
                  className="h-12 rounded-xl"
                />
              </div>
              <Button
                type="button"
                onClick={handleCreateMedicine}
                disabled={createMedicineMutation.isPending}
                className="h-12 rounded-xl"
              >
                {createMedicineMutation.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <PackagePlus className="mr-2 h-4 w-4" />
                )}
                Save Medicine
              </Button>
            </CardContent>
          </Card>

          <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Excel Branch Pricing</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="rounded-xl border bg-background/65 p-4">
                <div className="flex items-start gap-3">
                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-success/10 text-success">
                    <FileText className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="font-semibold">Download, price, upload</p>
                    <p className="mt-1 text-sm text-muted-foreground">
                      The file includes every master drug. The branch fills
                      stock, reorder level, buying price, and selling price.
                    </p>
                  </div>
                </div>
              </div>
              <input
                ref={fileInputRef}
                type="file"
                accept=".csv,text/csv"
                className="hidden"
                onChange={handleImportTemplate}
              />
              <div className="grid gap-3 sm:grid-cols-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleDownloadTemplate}
                  disabled={!selectedBranchId || isDownloadingTemplate}
                  className="h-12 rounded-xl"
                >
                  {isDownloadingTemplate ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <Download className="mr-2 h-4 w-4" />
                  )}
                  Download CSV
                </Button>
                <Button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={
                    !selectedBranchId || importPricingMutation.isPending
                  }
                  className="h-12 rounded-xl"
                >
                  {importPricingMutation.isPending ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <Upload className="mr-2 h-4 w-4" />
                  )}
                  Import CSV
                </Button>
              </div>
            </CardContent>
          </Card>

          <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Drug Reorder</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="mb-2 block text-sm font-medium">
                  Search Drug
                </label>
                <Input
                  value={reorderSearch}
                  onChange={(event) => setReorderSearch(event.target.value)}
                  className="mb-2 h-12 rounded-xl"
                  placeholder="Search medicine name, code, strength, or form"
                  disabled={!selectedBranchId}
                />
                <select
                  value={selectedReorderStockId}
                  onChange={(event) =>
                    setSelectedReorderStockId(event.target.value)
                  }
                  className={appSelectClass}
                  disabled={!selectedBranchId}
                >
                  <option value="">Select branch stock item</option>
                  {filteredReorderStock.map((stock) => (
                    <option key={stock.id} value={String(stock.id)}>
                      {medicineLabel(stock.medicine)}
                    </option>
                  ))}
                </select>
              </div>

              {activeReorderStock ? (
                <div className="grid gap-3 rounded-xl border bg-background/65 p-4 text-sm md:grid-cols-3">
                  <div>
                    <p className="text-xs uppercase text-muted-foreground">
                      Current Stock
                    </p>
                    <p className="mt-1 font-bold">
                      {activeReorderStock.stockQuantity}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase text-muted-foreground">
                      Reorder Level
                    </p>
                    <p className="mt-1 font-bold">
                      {activeReorderStock.reorderLevel}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs uppercase text-muted-foreground">
                      Unit
                    </p>
                    <p className="mt-1 font-bold">
                      {[
                        activeReorderStock.medicine?.dosageForm,
                        activeReorderStock.medicine?.strength,
                      ]
                        .filter(Boolean)
                        .join(" / ") || "Unit"}
                    </p>
                  </div>
                </div>
              ) : null}

              <div className="grid gap-4 md:grid-cols-3">
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Reordered Amount
                  </label>
                  <Input
                    type="number"
                    value={reorderQuantity}
                    onChange={(event) => setReorderQuantity(event.target.value)}
                    className="h-12 rounded-xl"
                    disabled={!activeReorderStock}
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Buying Price
                  </label>
                  <Input
                    type="number"
                    value={reorderBuyingPrice}
                    onChange={(event) =>
                      setReorderBuyingPrice(event.target.value)
                    }
                    className="h-12 rounded-xl"
                    disabled={!activeReorderStock}
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Selling Price
                  </label>
                  <Input
                    type="number"
                    value={reorderUnitPrice}
                    onChange={(event) =>
                      setReorderUnitPrice(event.target.value)
                    }
                    className="h-12 rounded-xl"
                    disabled={!activeReorderStock}
                  />
                </div>
              </div>

              <Button
                type="button"
                onClick={handleRestock}
                disabled={
                  restockMutation.isPending ||
                  !selectedBranchId ||
                  !activeReorderStock
                }
                className="h-12 rounded-xl"
              >
                {restockMutation.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <PackagePlus className="mr-2 h-4 w-4" />
                )}
                Receive Reorder
              </Button>
            </CardContent>
          </Card>

          <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Add Branch Price</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <label className="mb-2 block text-sm font-medium">
                  Medicine
                </label>
                <Input
                  value={medicinePickerSearch}
                  onChange={(event) =>
                    setMedicinePickerSearch(event.target.value)
                  }
                  className="mb-2 h-12 rounded-xl"
                  placeholder="Search drug name, code, form, or strength"
                  disabled={!selectedBranchId}
                />
                <select
                  value={selectedMedicineId}
                  onChange={(event) =>
                    setSelectedMedicineId(event.target.value)
                  }
                  className={appSelectClass}
                  disabled={!selectedBranchId}
                >
                  <option value="">Select medicine</option>
                  {filteredUnmappedMedicines.map((medicine) => (
                    <option key={medicine.id} value={String(medicine.id)}>
                      {medicineLabel(medicine)}
                    </option>
                  ))}
                </select>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Initial Stock
                  </label>
                  <Input
                    type="number"
                    value={initialStock}
                    onChange={(event) => setInitialStock(event.target.value)}
                    className="h-12 rounded-xl"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Reorder Level
                  </label>
                  <Input
                    type="number"
                    value={branchReorderLevel}
                    onChange={(event) =>
                      setBranchReorderLevel(event.target.value)
                    }
                    className="h-12 rounded-xl"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Buying Price
                  </label>
                  <Input
                    type="number"
                    value={branchBuyingPrice}
                    onChange={(event) =>
                      setBranchBuyingPrice(event.target.value)
                    }
                    className="h-12 rounded-xl"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Branch Price
                  </label>
                  <Input
                    type="number"
                    value={branchUnitPrice}
                    onChange={(event) => setBranchUnitPrice(event.target.value)}
                    className="h-12 rounded-xl"
                  />
                </div>
              </div>
              <Button
                type="button"
                onClick={handleCreateBranchStock}
                disabled={createStockMutation.isPending || !selectedBranchId}
                className="h-12 rounded-xl"
              >
                {createStockMutation.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Save className="mr-2 h-4 w-4" />
                )}
                Save Branch Price
              </Button>
            </CardContent>
          </Card>
        </div>

        <Card className="rounded-[1.2rem] surface-spotlight shadow-md">
          <CardHeader>
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <CardTitle>Branch Price Register</CardTitle>
              <div className="relative w-full lg:max-w-xs">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  value={search}
                  onChange={(event) => setSearch(event.target.value)}
                  className="h-11 rounded-xl pl-9"
                  placeholder="Search medicines"
                />
              </div>
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            {medicinesLoading || stockLoading ? (
              <div className="text-sm text-muted-foreground">
                Loading pharmacy pricing...
              </div>
            ) : !selectedBranchId ? (
              <div className="rounded-xl border border-dashed bg-background/65 p-4 text-sm text-muted-foreground">
                Select a branch to manage prices.
              </div>
            ) : filteredStock.length === 0 ? (
              <div className="rounded-xl border border-dashed bg-background/65 p-4 text-sm text-muted-foreground">
                No branch price records found.
              </div>
            ) : (
              <div className="max-h-[620px] overflow-auto rounded-xl border bg-background/65">
                <table className="w-full min-w-[1040px] text-left text-sm">
                  <thead className="sticky top-0 z-10 bg-muted text-xs uppercase text-muted-foreground">
                    <tr>
                      <th className="px-4 py-3 font-semibold">Code</th>
                      <th className="px-4 py-3 font-semibold">Medicine</th>
                      <th className="px-4 py-3 font-semibold">Stock</th>
                      <th className="px-4 py-3 font-semibold">Reorder</th>
                      <th className="px-4 py-3 font-semibold">Buying</th>
                      <th className="px-4 py-3 font-semibold">Selling</th>
                      <th className="px-4 py-3 font-semibold">Margin</th>
                      <th className="px-4 py-3 font-semibold">Value</th>
                      <th className="px-4 py-3 font-semibold">Status</th>
                      <th className="px-4 py-3 font-semibold">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredStock.map((stock) => {
                      const isEditing = editingStockId === stock.id;
                      const margin = stock.unitPrice - stock.buyingPrice;

                      return (
                        <tr
                          key={stock.id}
                          className="border-t align-top transition hover:bg-muted/35"
                        >
                          <td className="px-4 py-4">
                            <Badge variant="outline" className="rounded-full">
                              {stock.medicine?.code ||
                                `MED-${stock.medicineId}`}
                            </Badge>
                          </td>
                          <td className="px-4 py-4">
                            <p className="font-semibold">
                              {medicineLabel(stock.medicine)}
                            </p>
                            <p className="mt-1 text-xs text-muted-foreground">
                              {stock.medicine?.manufacturer ||
                                "No manufacturer"}
                            </p>
                          </td>
                          <td className="px-4 py-4">
                            {isEditing ? (
                              <Input
                                type="number"
                                value={editStockQuantity}
                                onChange={(event) =>
                                  setEditStockQuantity(event.target.value)
                                }
                                className="h-10 min-w-24 rounded-xl"
                              />
                            ) : (
                              stock.stockQuantity
                            )}
                          </td>
                          <td className="px-4 py-4">
                            {isEditing ? (
                              <Input
                                type="number"
                                value={editReorderLevel}
                                onChange={(event) =>
                                  setEditReorderLevel(event.target.value)
                                }
                                className="h-10 min-w-24 rounded-xl"
                              />
                            ) : (
                              stock.reorderLevel
                            )}
                          </td>
                          <td className="px-4 py-4">
                            {isEditing ? (
                              <Input
                                type="number"
                                value={editBuyingPrice}
                                onChange={(event) =>
                                  setEditBuyingPrice(event.target.value)
                                }
                                className="h-10 min-w-28 rounded-xl"
                              />
                            ) : (
                              formatMoney(stock.buyingPrice)
                            )}
                          </td>
                          <td className="px-4 py-4">
                            {isEditing ? (
                              <Input
                                type="number"
                                value={editUnitPrice}
                                onChange={(event) =>
                                  setEditUnitPrice(event.target.value)
                                }
                                className="h-10 min-w-28 rounded-xl"
                              />
                            ) : (
                              formatMoney(stock.unitPrice)
                            )}
                          </td>
                          <td className="px-4 py-4">
                            <span
                              className={
                                margin >= 0
                                  ? "font-semibold text-success"
                                  : "font-semibold text-destructive"
                              }
                            >
                              {formatMoney(margin)}
                            </span>
                          </td>
                          <td className="px-4 py-4">
                            {formatMoney(stock.unitPrice * stock.stockQuantity)}
                          </td>
                          <td className="px-4 py-4">
                            {stock.unitPrice <= 0 ? (
                              <Badge className="rounded-full border-0 bg-amber-500/10 text-warning">
                                Missing price
                              </Badge>
                            ) : stock.stockQuantity <= stock.reorderLevel ? (
                              <Badge className="rounded-full border-0 bg-destructive/10 text-destructive">
                                Reorder
                              </Badge>
                            ) : (
                              <Badge className="rounded-full border-0 bg-success/10 text-success">
                                Ready
                              </Badge>
                            )}
                          </td>
                          <td className="px-4 py-4">
                            {isEditing ? (
                              <div className="flex gap-2">
                                <Button
                                  type="button"
                                  size="sm"
                                  className="rounded-xl"
                                  onClick={handleSaveEdit}
                                  disabled={updateStockMutation.isPending}
                                >
                                  {updateStockMutation.isPending ? (
                                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                  ) : (
                                    <Save className="mr-2 h-4 w-4" />
                                  )}
                                  Save
                                </Button>
                                <Button
                                  type="button"
                                  size="sm"
                                  variant="outline"
                                  className="rounded-xl"
                                  onClick={() => setEditingStockId(null)}
                                >
                                  Cancel
                                </Button>
                              </div>
                            ) : (
                              <Button
                                type="button"
                                size="sm"
                                variant="outline"
                                className="rounded-xl"
                                onClick={() => handleStartEdit(stock)}
                              >
                                Edit
                              </Button>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

"use client";

import * as React from "react";
import {
  AlertTriangle,
  CheckCircle2,
  Loader2,
  Package,
  Pill,
  RefreshCw,
  Search,
  Warehouse,
} from "lucide-react";

import { useScope } from "@/providers/scope-provider";
import { useBranchPharmacyStock } from "@/hooks/use-branch-pharmacy-stock";
import { useLowPharmacyStock } from "@/hooks/use-low-pharmacy-stock";
import { useRestockBranchMedicine } from "@/hooks/use-restock-branch-medicine";
import type { BranchMedicineStockItem } from "@/services/pharmacy-stock-service";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";

function stockTone(item: BranchMedicineStockItem) {
  if (item.stockQuantity <= 0) {
    return "border-red-500/20 bg-red-500/10 text-red-300";
  }

  if (item.stockQuantity <= item.reorderLevel) {
    return "border-amber-500/20 bg-amber-500/10 text-amber-300";
  }

  return "border-emerald-500/20 bg-success/10 text-emerald-300";
}

function stockLabel(item: BranchMedicineStockItem) {
  if (item.stockQuantity <= 0) return "OUT OF STOCK";
  if (item.stockQuantity <= item.reorderLevel) return "LOW STOCK";
  return "IN STOCK";
}

function formatMoney(value?: number | null) {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "KES",
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

export default function PharmacyStockPage() {
  const { selectedBranchId, selectedBranchName, facilityName } = useScope();

  const [search, setSearch] = React.useState("");
  const [page, setPage] = React.useState(1);
  const pageSize = 25;
  const deferredSearch = React.useDeferredValue(search);
  const { data, isLoading } = useBranchPharmacyStock(selectedBranchId, {
    page,
    pageSize,
    search: deferredSearch,
  });
  const { data: lowStockData } = useLowPharmacyStock();
  const restockMutation = useRestockBranchMedicine();

  const stocks = Array.isArray(data) ? data : (data?.data ?? []);
  const stockMeta = Array.isArray(data) ? undefined : data?.meta;
  const [message, setMessage] = React.useState<string | null>(null);

  const [activeStockId, setActiveStockId] = React.useState<number | null>(null);
  const [quantityToAdd, setQuantityToAdd] = React.useState("");
  const [reorderLevel, setReorderLevel] = React.useState("");
  const [unitPrice, setUnitPrice] = React.useState("");

  React.useEffect(() => {
    setPage(1);
  }, [deferredSearch, selectedBranchId]);

  const totalItems = stockMeta?.total ?? stocks.length;
  const lowStockCount = stocks.filter(
    (item) => item.stockQuantity > 0 && item.stockQuantity <= item.reorderLevel,
  ).length;
  const outOfStockCount = stocks.filter((item) => item.stockQuantity <= 0).length;
  const inStockCount = stocks.filter(
    (item) => item.stockQuantity > item.reorderLevel,
  ).length;
  const missingPriceCount = stocks.filter((item) => item.unitPrice <= 0).length;
  const totalStockValue = stocks.reduce(
    (sum, item) => sum + item.stockQuantity * item.unitPrice,
    0,
  );

  const activeStock =
    stocks.find((item) => item.id === activeStockId) ?? null;

  React.useEffect(() => {
    if (!activeStock) return;
    setReorderLevel(String(activeStock.reorderLevel ?? 0));
    setUnitPrice(String(activeStock.unitPrice ?? 0));
  }, [activeStockId]);

  const handleOpenRestock = (item: BranchMedicineStockItem) => {
    setActiveStockId(item.id);
    setQuantityToAdd("");
    setReorderLevel(String(item.reorderLevel ?? 0));
    setUnitPrice(String(item.unitPrice ?? 0));
    setMessage(null);
  };

  const handleRestock = async () => {
    if (!activeStock) return;

    const qty = Number(quantityToAdd);
    if (!qty || qty <= 0) {
      setMessage("Enter a valid quantity to add.");
      return;
    }

    setMessage(null);

    await restockMutation.mutateAsync({
      stockId: activeStock.id,
      payload: {
        quantityToAdd: qty,
        reorderLevel: reorderLevel ? Number(reorderLevel) : undefined,
        unitPrice: unitPrice ? Number(unitPrice) : undefined,
      },
    });

    setQuantityToAdd("");
    setActiveStockId(null);
    setMessage("Medicine stock restocked successfully.");
    setReorderLevel("");
    setUnitPrice("");
  };

  return (
    <div className="space-y-6">
      <section className="relative overflow-hidden rounded-[2rem] border surface-spotlight shadow-md p-6 md:p-8">
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-cyan-600/10 via-cyan-500/5 to-transparent" />

        <div className="relative flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
          <div className="space-y-3">
            <Badge className="rounded-full border-0 bg-cyan-600/10 px-3 py-1 text-module">
              Pharmacy Stock
            </Badge>

            <div className="flex items-center gap-3">
              <div className="flex h-14 w-14 items-center justify-center rounded-3xl bg-primary/10">
                <Warehouse className="h-7 w-7 text-primary" />
              </div>

              <div>
                <h1 className="text-3xl font-bold tracking-tight md:text-4xl">
                  Branch Pharmacy Stock
                </h1>
                <p className="text-muted-foreground">
                  Control branch stock, reorder levels, and dispensing prices
                </p>
              </div>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-2 xl:w-[420px]">
            <div className="rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-4">
              <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">
                Facility
              </p>
              <p className="mt-2 text-sm font-semibold">{facilityName || "No facility"}</p>
            </div>

            <div className="rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-4">
              <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">
                Branch
              </p>
              <p className="mt-2 text-sm font-semibold">
                {selectedBranchName || "No branch"}
              </p>
            </div>
          </div>
        </div>
      </section>

      {message ? (
        <div className="rounded-[1.4rem] border border-cyan-500/20 bg-cyan-500/8 px-4 py-4 text-sm text-cyan-300">
          {message}
        </div>
      ) : null}

      <section className="grid gap-6 md:grid-cols-2 xl:grid-cols-5">
        <Card className="rounded-[1.6rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Stock Items</p>
              <p className="mt-2 text-2xl font-bold">{totalItems}</p>
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10">
              <Package className="h-6 w-6 text-primary" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[1.6rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">In Stock</p>
              <p className="mt-2 text-2xl font-bold">{inStockCount}</p>
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10">
              <CheckCircle2 className="h-6 w-6 text-primary" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[1.6rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Low Stock</p>
              <p className="mt-2 text-2xl font-bold">{lowStockCount}</p>
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10">
              <AlertTriangle className="h-6 w-6 text-primary" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[1.6rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Out of Stock</p>
              <p className="mt-2 text-2xl font-bold">{outOfStockCount}</p>
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10">
              <Pill className="h-6 w-6 text-primary" />
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-[1.6rem] surface-spotlight shadow-md">
          <CardContent className="flex items-center justify-between p-5">
            <div>
              <p className="text-sm text-muted-foreground">Stock Value</p>
              <p className="mt-2 text-xl font-bold">
                {formatMoney(totalStockValue)}
              </p>
              {missingPriceCount > 0 ? (
                <p className="mt-1 text-xs text-warning">
                  {missingPriceCount} missing prices
                </p>
              ) : null}
            </div>
            <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary/10">
              <Pill className="h-6 w-6 text-primary" />
            </div>
          </CardContent>
        </Card>
      </section>

      <section className="grid gap-6 xl:grid-cols-[1.15fr_0.85fr]">
        <Card className="rounded-[1.8rem] surface-spotlight shadow-md">
          <CardHeader>
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <CardTitle>Branch Stock List</CardTitle>
              <div className="relative w-full lg:max-w-xs">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  value={search}
                  onChange={(event) => setSearch(event.target.value)}
                  className="h-11 rounded-xl pl-9"
                  placeholder="Search medicine, code, form"
                />
              </div>
            </div>
          </CardHeader>

          <CardContent className="space-y-4">
            {isLoading ? (
              <div className="text-sm text-muted-foreground">Loading stock...</div>
            ) : stocks.length === 0 ? (
              <div className="rounded-[1.2rem] border border-dashed border-white/10 bg-card/[0.02] p-5 text-sm text-muted-foreground">
                No branch medicine stock records matched.
              </div>
            ) : (
              <>
                {stocks.map((item) => (
                  <div
                    key={item.id}
                    className="rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-4"
                  >
                    <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                      <div className="space-y-2">
                        <p className="font-semibold">
                          {item.medicine?.name || `Medicine #${item.medicineId}`}
                        </p>

                        <p className="text-sm text-muted-foreground">
                          {[item.medicine?.code, item.medicine?.dosageForm, item.medicine?.strength]
                            .filter(Boolean)
                            .join(" / ") || "-"}
                        </p>

                        <div className="grid gap-3 md:grid-cols-3">
                          <div className="rounded-[1rem] border border-white/10 bg-card/[0.03] p-3">
                            <p className="text-xs text-muted-foreground">Stock Quantity</p>
                            <p className="mt-1 text-sm font-medium">{item.stockQuantity}</p>
                          </div>

                          <div className="rounded-[1rem] border border-white/10 bg-card/[0.03] p-3">
                            <p className="text-xs text-muted-foreground">Reorder Level</p>
                            <p className="mt-1 text-sm font-medium">{item.reorderLevel}</p>
                          </div>

                          <div className="rounded-[1rem] border border-white/10 bg-card/[0.03] p-3">
                            <p className="text-xs text-muted-foreground">Unit Price</p>
                            <p className="mt-1 text-sm font-medium">
                              {formatMoney(item.unitPrice)}
                            </p>
                            {item.unitPrice <= 0 ? (
                              <p className="mt-1 text-xs text-warning">
                                Fix before dispensing
                              </p>
                            ) : null}
                          </div>
                        </div>
                      </div>

                      <div className="flex flex-col gap-2">
                        <Badge className={`rounded-full border px-3 py-1 ${stockTone(item)}`}>
                          {stockLabel(item)}
                        </Badge>

                        <Button
                          type="button"
                          variant="outline"
                          className="rounded-2xl"
                          onClick={() => handleOpenRestock(item)}
                        >
                          <RefreshCw className="mr-2 h-4 w-4" />
                          Restock
                        </Button>
                      </div>
                    </div>
                  </div>
                ))}
                {stockMeta ? (
                  <div className="flex flex-col gap-3 rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-3 text-sm md:flex-row md:items-center md:justify-between">
                    <span className="text-muted-foreground">
                      Page {stockMeta.page} of {stockMeta.totalPages} /
                      showing {stocks.length} of {stockMeta.total}
                    </span>
                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setPage((current) => Math.max(1, current - 1))}
                        disabled={stockMeta.page <= 1 || isLoading}
                      >
                        Previous
                      </Button>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setPage((current) => current + 1)}
                        disabled={!stockMeta.hasNextPage || isLoading}
                      >
                        Next
                      </Button>
                    </div>
                  </div>
                ) : null}
              </>
            )}
          </CardContent>
        </Card>

        <div className="space-y-6">
          <Card className="rounded-[1.8rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Restock Medicine</CardTitle>
            </CardHeader>

            <CardContent className="space-y-4">
              {!activeStock ? (
                <div className="rounded-[1.2rem] border border-dashed border-white/10 bg-card/[0.02] p-5 text-sm text-muted-foreground">
                  Select a medicine stock item and click Restock.
                </div>
              ) : (
                <>
                  <div className="rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-4">
                    <p className="font-semibold">
                      {activeStock.medicine?.name || `Medicine #${activeStock.medicineId}`}
                    </p>
                    <p className="mt-1 text-sm text-muted-foreground">
                      Current stock: {activeStock.stockQuantity}
                    </p>
                  </div>

                  <div>
                    <label className="mb-2 block text-sm font-medium">Quantity to Add</label>
                    <Input
                      type="number"
                      value={quantityToAdd}
                      onChange={(e) => setQuantityToAdd(e.target.value)}
                      className="h-12 rounded-2xl"
                      placeholder="50"
                    />
                  </div>

                  <div>
                    <label className="mb-2 block text-sm font-medium">Reorder Level</label>
                    <Input
                      type="number"
                      value={reorderLevel}
                      onChange={(e) => setReorderLevel(e.target.value)}
                      className="h-12 rounded-2xl"
                      placeholder="10"
                    />
                  </div>

                  <div>
                    <label className="mb-2 block text-sm font-medium">Unit Price</label>
                    <Input
                      type="number"
                      value={unitPrice}
                      onChange={(e) => setUnitPrice(e.target.value)}
                      className="h-12 rounded-2xl"
                      placeholder="25"
                    />
                  </div>

                  <Button
                    type="button"
                    className="h-12 rounded-2xl"
                    onClick={handleRestock}
                    disabled={restockMutation.isPending}
                  >
                    {restockMutation.isPending ? (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    ) : (
                      <RefreshCw className="mr-2 h-4 w-4" />
                    )}
                    Save Restock
                  </Button>
                </>
              )}
            </CardContent>
          </Card>

          <Card className="rounded-[1.8rem] surface-spotlight shadow-md">
            <CardHeader>
              <CardTitle>Low Stock Monitor</CardTitle>
            </CardHeader>

            <CardContent className="space-y-3">
              {!(lowStockData?.lowStockItems?.length || lowStockData?.outOfStockItems?.length) ? (
                <div className="rounded-[1.2rem] border border-dashed border-white/10 bg-card/[0.02] p-4 text-sm text-muted-foreground">
                  No low-stock alerts right now.
                </div>
              ) : (
                <>
                  {(lowStockData?.outOfStockItems ?? []).map((item) => (
                    <div
                      key={`out-${item.id}`}
                      className="rounded-[1rem] border border-red-500/20 bg-red-500/10 p-4"
                    >
                      <p className="font-medium text-red-300">{item.medicineName || "Unknown medicine"}</p>
                      <p className="mt-1 text-sm text-muted-foreground">
                        Out of stock / Reorder level: {item.reorderLevel}
                      </p>
                    </div>
                  ))}

                  {(lowStockData?.lowStockItems ?? []).map((item) => (
                    <div
                      key={`low-${item.id}`}
                      className="rounded-[1rem] border border-amber-500/20 bg-amber-500/10 p-4"
                    >
                      <p className="font-medium text-amber-300">{item.medicineName || "Unknown medicine"}</p>
                      <p className="mt-1 text-sm text-muted-foreground">
                        Stock: {item.stockQuantity} / Reorder level: {item.reorderLevel}
                      </p>
                    </div>
                  ))}
                </>
              )}
            </CardContent>
          </Card>
        </div>
      </section>
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import {
  Banknote,
  CheckCircle2,
  CreditCard,
  Loader2,
  Pill,
  Plus,
  Printer,
  RefreshCw,
  Search,
  ShieldCheck,
  Trash2,
} from "lucide-react";
import { useQuery } from "@tanstack/react-query";

import { useAuth } from "@/providers/auth-provider";
import { useScope } from "@/providers/scope-provider";
import { useDebouncedValue } from "@/hooks/use-branch-medicine-search";
import {
  addOtcSaleItem,
  completeOtcSale,
  createOtcSale,
  downloadOtcReceiptPdf,
  recordOtcSalePayment,
  removeOtcSaleItem,
  searchOtcMedicines,
  updateOtcSaleItem,
  type InsuranceClaimStatus,
  type OtcMedicineSearchItem,
  type OtcPaymentMethod,
  type OtcSale,
  type OtcSalePaymentInput,
} from "@/services/otc-sales-service";
import { ApiError } from "@/lib/api";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

const OTC_ROLES = new Set([
  "SUPER_ADMIN",
  "ADMIN",
  "FACILITY_ADMIN",
  "BRANCH_ADMIN",
  "PHARMACIST",
  "PHARMACY_MANAGER",
  "CASHIER",
  "BILLING_OFFICER",
]);

const PAYMENT_METHODS: Array<{ value: OtcPaymentMethod; label: string }> = [
  { value: "CASH", label: "Cash" },
  { value: "MPESA_MANUAL", label: "M-Pesa Manual" },
  { value: "MPESA_STK", label: "M-Pesa STK" },
  { value: "CARD", label: "Card" },
  { value: "BANK", label: "Bank" },
  { value: "INSURANCE", label: "Insurance" },
];

const CLAIM_STATUSES: InsuranceClaimStatus[] = [
  "DRAFT",
  "PENDING_APPROVAL",
  "APPROVED",
  "PARTIALLY_APPROVED",
  "REJECTED",
  "PAID",
  "CANCELLED",
];

type PaymentDraft = OtcSalePaymentInput & { localId: string };

function formatMoney(value?: number | null) {
  return new Intl.NumberFormat(undefined, {
    style: "currency",
    currency: "KES",
    maximumFractionDigits: 2,
  }).format(Number(value || 0));
}

function extractError(error: unknown) {
  if (error instanceof ApiError || error instanceof Error) return error.message;
  return "The OTC sale request failed. Please retry.";
}

function stockTone(status: string) {
  switch (status) {
    case "IN_STOCK":
      return "bg-success-soft text-success ring-emerald-200";
    case "LOW_STOCK":
      return "bg-warning-soft text-warning ring-amber-200";
    default:
      return "bg-destructive-soft text-destructive ring-rose-200";
  }
}

function paymentStatusTone(status?: string | null) {
  switch ((status || "").toUpperCase()) {
    case "PAID":
      return "bg-success-soft text-success ring-emerald-200";
    case "PENDING_INSURANCE":
      return "bg-warning-soft text-warning ring-amber-200";
    case "PARTIALLY_PAID":
      return "bg-blue-50 text-module ring-blue-200";
    default:
      return "bg-muted text-muted-foreground ring-slate-200";
  }
}

function saleCanShowReceipt(sale?: OtcSale | null) {
  if (!sale) return false;
  return ["PAID", "PENDING_INSURANCE", "PARTIALLY_PAID"].includes(
    sale.paymentStatus,
  );
}

function localPaymentId() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID();
  }
  return `payment-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function newPaymentDraft(method: OtcPaymentMethod = "CASH"): PaymentDraft {
  return {
    localId: localPaymentId(),
    paymentMethod: method,
    amount: 0,
    insuranceClaimStatus: method === "INSURANCE" ? "DRAFT" : undefined,
  };
}

export default function OtcSalesPage() {
  const { user } = useAuth();
  const {
    facilityName,
    selectedBranchId,
    selectedBranchName,
    availableBranches,
    canSwitchBranches,
    setSelectedBranchId,
  } = useScope();

  const [sale, setSale] = React.useState<OtcSale | null>(null);
  const [customerName, setCustomerName] = React.useState("");
  const [customerPhone, setCustomerPhone] = React.useState("");
  const [notes, setNotes] = React.useState("");
  const [searchText, setSearchText] = React.useState("");
  const debouncedSearch = useDebouncedValue(searchText, 250);
  const [selectedMedicine, setSelectedMedicine] =
    React.useState<OtcMedicineSearchItem | null>(null);
  const [quantity, setQuantity] = React.useState(1);
  const [unitPrice, setUnitPrice] = React.useState(0);
  const [paymentRows, setPaymentRows] = React.useState<PaymentDraft[]>([
    newPaymentDraft("CASH"),
  ]);
  const [busy, setBusy] = React.useState<string | null>(null);
  const [message, setMessage] = React.useState<string | null>(null);
  const [error, setError] = React.useState<string | null>(null);

  const roleCode = user?.roleCode ?? "";
  const isAllowed = OTC_ROLES.has(roleCode);
  const branchRequired = !selectedBranchId;
  const queryEnabled =
    isAllowed && Boolean(selectedBranchId) && debouncedSearch.trim().length >= 2;

  const medicineQuery = useQuery({
    queryKey: ["otc-medicine-search", selectedBranchId, debouncedSearch],
    queryFn: () =>
      searchOtcMedicines({
        query: debouncedSearch,
        branchId: selectedBranchId,
        pageSize: 12,
      }),
    enabled: queryEnabled,
    staleTime: 15_000,
    placeholderData: (previousData) => previousData,
  });

  React.useEffect(() => {
    if (selectedMedicine) {
      setUnitPrice(selectedMedicine.unitPrice);
      setQuantity(1);
    }
  }, [selectedMedicine]);

  React.useEffect(() => {
    if (!sale) {
      const total = selectedMedicine
        ? Math.max(1, quantity) * Number(unitPrice || 0)
        : 0;
      setPaymentRows((rows) =>
        rows.length === 1 && rows[0].paymentMethod === "CASH"
          ? [{ ...rows[0], amount: total }]
          : rows,
      );
    }
  }, [quantity, sale, selectedMedicine, unitPrice]);

  const lineTotal = React.useMemo(
    () => Math.max(0, Number(quantity || 0)) * Number(unitPrice || 0),
    [quantity, unitPrice],
  );
  const optimisticSubtotal = React.useMemo(
    () =>
      sale?.items.reduce((sum, item) => sum + Number(item.lineTotal || 0), 0) ??
      0,
    [sale],
  );
  const totalDue = sale?.totalAmount ?? optimisticSubtotal;
  const paymentPreview = React.useMemo(() => {
    const counted = paymentRows.reduce((sum, row) => {
      if (row.paymentMethod === "INSURANCE") {
        return ["APPROVED", "PARTIALLY_APPROVED", "PAID"].includes(
          row.insuranceClaimStatus || "",
        )
          ? sum + Number(row.insuranceCoveredAmount || row.amount || 0)
          : sum;
      }
      return sum + Number(row.amount || 0);
    }, 0);
    return {
      amount: counted,
      balance: Math.max(totalDue - counted, 0),
    };
  }, [paymentRows, totalDue]);

  const mutate = async <T,>(label: string, action: () => Promise<T>) => {
    setBusy(label);
    setError(null);
    setMessage(null);
    try {
      return await action();
    } catch (err) {
      setError(extractError(err));
      throw err;
    } finally {
      setBusy(null);
    }
  };

  const ensureSale = async () => {
    if (sale) return sale;
    if (!selectedBranchId) throw new Error("Select a branch before selling.");

    const created = await createOtcSale({
      branchId: selectedBranchId,
      customerName: customerName.trim() || undefined,
      customerPhone: customerPhone.trim() || undefined,
      notes: notes.trim() || undefined,
    });
    setSale(created);
    return created;
  };

  const handleAddItem = async () => {
    if (!selectedMedicine) {
      setError("Select a medicine first.");
      return;
    }
    if (selectedMedicine.stockStatus === "OUT_OF_STOCK") {
      setError("This medicine is out of stock.");
      return;
    }
    if (quantity < 1 || quantity > selectedMedicine.currentStock) {
      setError("Quantity must be positive and cannot exceed current stock.");
      return;
    }

    await mutate("item", async () => {
      const currentSale = await ensureSale();
      const updated = await addOtcSaleItem(currentSale.id, {
        medicineId: selectedMedicine.medicineId,
        quantity,
        unitPrice,
      });
      setSale(updated);
      setSelectedMedicine(null);
      setSearchText("");
      setQuantity(1);
      setUnitPrice(0);
      setMessage("Medicine added to OTC sale.");
    });
  };

  const handleUpdateItem = async (
    itemId: number,
    nextQuantity: number,
    unit: number,
  ) => {
    if (!sale) return;
    await mutate(`item-${itemId}`, async () => {
      const updated = await updateOtcSaleItem(sale.id, itemId, {
        quantity: nextQuantity,
        unitPrice: unit,
      });
      setSale(updated);
    });
  };

  const handleRemoveItem = async (itemId: number) => {
    if (!sale) return;
    await mutate(`remove-${itemId}`, async () => {
      const updated = await removeOtcSaleItem(sale.id, itemId);
      setSale(updated);
      setMessage("Item removed.");
    });
  };

  const handleRecordPayment = async () => {
    if (!sale) {
      setError("Add at least one medicine before payment.");
      return null;
    }
    if (sale.items.length === 0) {
      setError("Add at least one medicine before payment.");
      return null;
    }

    const payload = paymentRows
      .map(({ localId: _localId, ...row }) => row)
      .filter((row) => {
        if (row.paymentMethod === "INSURANCE") {
          return row.insuranceProviderName || row.insuranceMemberNumber;
        }
        return Number(row.amount || 0) > 0;
      });

    if (payload.length === 0) {
      setError("Enter at least one valid payment line.");
      return null;
    }

    return mutate("payment", async () => {
      const updated = await recordOtcSalePayment(sale.id, payload);
      setSale(updated);
      setMessage("Payment recorded. Complete the sale once fully paid.");
      return updated;
    });
  };

  const handleComplete = async () => {
    if (!sale) return;
    await mutate("complete", async () => {
      const updated = await completeOtcSale(sale.id);
      setSale(updated);
      setMessage("OTC sale completed. Stock has been deducted.");
    });
  };

  const handlePayAndComplete = async () => {
    const paidSale = await handleRecordPayment();
    if (!paidSale) return;
    if (paidSale.paymentStatus !== "PAID") {
      setMessage(
        paidSale.paymentStatus === "PENDING_INSURANCE"
          ? "Insurance is pending. Stock will not deduct until coverage and co-pay are fully approved."
          : "Payment recorded. Complete once balance is cleared.",
      );
      return;
    }
    await mutate("complete", async () => {
      const completed = await completeOtcSale(paidSale.id);
      setSale(completed);
      setMessage("Payment accepted and stock deducted.");
    });
  };

  const resetSale = () => {
    setSale(null);
    setCustomerName("");
    setCustomerPhone("");
    setNotes("");
    setSearchText("");
    setSelectedMedicine(null);
    setPaymentRows([newPaymentDraft("CASH")]);
    setMessage(null);
    setError(null);
  };

  const updatePaymentRow = (
    localId: string,
    patch: Partial<OtcSalePaymentInput>,
  ) => {
    setPaymentRows((rows) =>
      rows.map((row) =>
        row.localId === localId
          ? {
              ...row,
              ...patch,
              insuranceClaimStatus:
                patch.paymentMethod === "INSURANCE" &&
                !row.insuranceClaimStatus
                  ? "DRAFT"
                  : patch.insuranceClaimStatus ?? row.insuranceClaimStatus,
            }
          : row,
      ),
    );
  };

  if (!isAllowed) {
    return (
      <div className="rounded-2xl border bg-card p-8 shadow-sm">
        <h1 className="text-2xl font-semibold">OTC Drug Sales</h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Your role does not have access to over-the-counter sale operations.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <section className="rounded-2xl border bg-card p-5 shadow-sm">
        <div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between">
          <div className="space-y-3">
            <Badge className="bg-cyan-50 text-module">Pharmacy POS</Badge>
            <div className="flex items-center gap-3">
              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-cyan-50">
                <Pill className="h-6 w-6 text-module" />
              </div>
              <div>
                <h1 className="text-2xl font-bold tracking-tight md:text-3xl">
                  Over Counter Drug Sale
                </h1>
                <p className="text-sm text-muted-foreground">
                  Search medicine, build cart, record payment, complete sale,
                  and deduct stock on one page.
                </p>
              </div>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-3 xl:w-[700px]">
            <div className="rounded-xl border bg-surface-2 p-3">
              <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">
                Facility
              </p>
              <p className="mt-1 truncate text-sm font-semibold">
                {facilityName || "No facility"}
              </p>
            </div>
            <div className="rounded-xl border bg-surface-2 p-3">
              <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">
                Branch
              </p>
              {canSwitchBranches && availableBranches.length > 0 ? (
                <select
                  value={selectedBranchId ?? ""}
                  onChange={(event) =>
                    setSelectedBranchId(
                      event.target.value ? Number(event.target.value) : undefined,
                    )
                  }
                  className="mt-1 h-8 w-full rounded-lg border bg-card px-2 text-sm"
                >
                  <option value="">Select branch</option>
                  {availableBranches.map((branch) => (
                    <option key={branch.id} value={branch.id}>
                      {branch.name}
                    </option>
                  ))}
                </select>
              ) : (
                <p className="mt-1 truncate text-sm font-semibold">
                  {selectedBranchName || "No branch"}
                </p>
              )}
            </div>
            <div className="rounded-xl border bg-surface-2 p-3">
              <p className="text-[11px] font-semibold uppercase tracking-[0.16em] text-muted-foreground">
                Sale
              </p>
              <p className="mt-1 truncate text-sm font-semibold">
                {sale?.saleNumber || "New sale"}
              </p>
            </div>
          </div>
        </div>
      </section>

      {branchRequired ? (
        <div className="rounded-xl border border-warning/30 bg-warning-soft px-4 py-3 text-sm text-warning">
          Select a branch before searching stock or creating an OTC sale.
        </div>
      ) : null}
      {message ? (
        <div className="rounded-xl border border-success/25 bg-success-soft px-4 py-3 text-sm text-success">
          {message}
        </div>
      ) : null}
      {error ? (
        <div className="rounded-xl border border-destructive/25 bg-destructive-soft px-4 py-3 text-sm text-rose-800">
          {error}
        </div>
      ) : null}

      <div className="grid gap-5 xl:grid-cols-[minmax(320px,0.9fr)_minmax(420px,1.2fr)_minmax(330px,0.85fr)]">
        <Card className="rounded-2xl border bg-card shadow-sm">
          <CardHeader>
            <CardTitle>Search and add drug</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="mb-1 block text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                  Customer name
                </label>
                <Input
                  value={customerName}
                  onChange={(event) => setCustomerName(event.target.value)}
                  disabled={Boolean(sale)}
                  placeholder="Optional walk-in name"
                  className="h-10"
                />
              </div>
              <div>
                <label className="mb-1 block text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                  Customer phone
                </label>
                <Input
                  value={customerPhone}
                  onChange={(event) => setCustomerPhone(event.target.value)}
                  disabled={Boolean(sale)}
                  placeholder="Optional phone"
                  className="h-10"
                />
              </div>
            </div>

            <div>
              <label className="mb-1 block text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                Medicine search
              </label>
              <div className="relative">
                <Search className="absolute left-3 top-2.5 h-4 w-4 text-subtle" />
                <Input
                  value={searchText}
                  onChange={(event) => setSearchText(event.target.value)}
                  disabled={branchRequired}
                  placeholder="Search by name, code, form, or strength"
                  className="h-10 pl-9"
                />
              </div>
            </div>

            <div className="max-h-[360px] space-y-2 overflow-y-auto pr-1">
              {medicineQuery.isFetching ? (
                <div className="flex items-center gap-2 rounded-xl border bg-surface-2 p-3 text-sm text-muted-foreground">
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Searching medicines...
                </div>
              ) : null}
              {queryEnabled &&
              !medicineQuery.isFetching &&
              (medicineQuery.data?.data.length ?? 0) === 0 ? (
                <div className="rounded-xl border bg-surface-2 p-3 text-sm text-muted-foreground">
                  No matching branch stock found.
                </div>
              ) : null}
              {(medicineQuery.data?.data ?? []).map((medicine) => (
                <button
                  type="button"
                  key={medicine.branchStockId}
                  onClick={() => setSelectedMedicine(medicine)}
                  className={cn(
                    "w-full rounded-xl border p-3 text-left transition hover:border-border-strong hover:bg-cyan-50/40",
                    selectedMedicine?.branchStockId === medicine.branchStockId &&
                      "border-cyan-400 bg-cyan-50",
                  )}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="font-semibold">{medicine.name}</p>
                      <p className="text-xs text-muted-foreground">
                        {[medicine.code, medicine.dosageForm, medicine.strength]
                          .filter(Boolean)
                          .join(" / ") || "No medicine details"}
                      </p>
                    </div>
                    <span
                      className={cn(
                        "rounded-full px-2 py-0.5 text-[11px] font-semibold ring-1",
                        stockTone(medicine.stockStatus),
                      )}
                    >
                      {medicine.stockStatus.replace(/_/g, " ")}
                    </span>
                  </div>
                  <div className="mt-3 grid grid-cols-3 gap-2 text-xs">
                    <div className="rounded-lg bg-card p-2">
                      <p className="text-muted-foreground">Stock</p>
                      <p className="font-semibold">{medicine.currentStock}</p>
                    </div>
                    <div className="rounded-lg bg-card p-2">
                      <p className="text-muted-foreground">Price</p>
                      <p className="font-semibold">
                        {formatMoney(medicine.unitPrice)}
                      </p>
                    </div>
                    <div className="rounded-lg bg-card p-2">
                      <p className="text-muted-foreground">Reorder</p>
                      <p className="font-semibold">{medicine.reorderLevel}</p>
                    </div>
                  </div>
                </button>
              ))}
            </div>

            <div className="rounded-xl border bg-surface-2 p-3">
              <p className="text-xs font-semibold uppercase tracking-[0.14em] text-muted-foreground">
                Selected drug
              </p>
              {selectedMedicine ? (
                <div className="mt-2 space-y-3">
                  <div>
                    <p className="font-semibold">{selectedMedicine.name}</p>
                    <p className="text-xs text-muted-foreground">
                      {selectedMedicine.currentStock} units available
                    </p>
                  </div>
                  <div className="grid gap-3 sm:grid-cols-3">
                    <div>
                      <label className="mb-1 block text-xs text-muted-foreground">
                        Quantity
                      </label>
                      <Input
                        type="number"
                        min={1}
                        max={selectedMedicine.currentStock}
                        value={quantity}
                        onChange={(event) =>
                          setQuantity(Number(event.target.value || 1))
                        }
                        className="h-10"
                      />
                    </div>
                    <div>
                      <label className="mb-1 block text-xs text-muted-foreground">
                        Unit price
                      </label>
                      <Input
                        type="number"
                        min={0}
                        value={unitPrice}
                        onChange={(event) =>
                          setUnitPrice(Number(event.target.value || 0))
                        }
                        className="h-10"
                      />
                    </div>
                    <div>
                      <label className="mb-1 block text-xs text-muted-foreground">
                        Line total
                      </label>
                      <div className="flex h-10 items-center rounded-lg border bg-card px-3 text-sm font-semibold">
                        {formatMoney(lineTotal)}
                      </div>
                    </div>
                  </div>
                  <Button
                    type="button"
                    onClick={handleAddItem}
                    disabled={Boolean(busy) || selectedMedicine.currentStock <= 0}
                    className="h-10 w-full"
                  >
                    {busy === "item" ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Plus className="h-4 w-4" />
                    )}
                    Add to sale
                  </Button>
                </div>
              ) : (
                <p className="mt-2 text-sm text-muted-foreground">
                  Search and select a medicine to add it to the cart.
                </p>
              )}
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-2xl border bg-card shadow-sm">
          <CardHeader>
            <div className="flex items-center justify-between gap-3">
              <CardTitle>Sale cart</CardTitle>
              <Badge
                className={cn(
                  "ring-1",
                  paymentStatusTone(sale?.paymentStatus || "UNPAID"),
                )}
              >
                {sale?.paymentStatus?.replace(/_/g, " ") || "UNPAID"}
              </Badge>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            {sale?.items.length ? (
              <div className="overflow-hidden rounded-xl border">
                <table className="w-full text-sm">
                  <thead className="bg-surface-2 text-left text-xs uppercase tracking-[0.12em] text-muted-foreground">
                    <tr>
                      <th className="px-3 py-2">Medicine</th>
                      <th className="px-3 py-2">Qty</th>
                      <th className="px-3 py-2">Unit</th>
                      <th className="px-3 py-2">Total</th>
                      <th className="px-3 py-2" />
                    </tr>
                  </thead>
                  <tbody>
                    {sale.items.map((item) => (
                      <tr key={item.id} className="border-t">
                        <td className="px-3 py-2">
                          <p className="font-medium">
                            {item.medicineNameSnapshot}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {[item.dosageFormSnapshot, item.strengthSnapshot]
                              .filter(Boolean)
                              .join(" / ") || "No form"}
                          </p>
                        </td>
                        <td className="px-3 py-2">
                          <Input
                            type="number"
                            min={1}
                            value={item.quantity}
                            disabled={sale.status === "PAID"}
                            onBlur={(event) =>
                              handleUpdateItem(
                                item.id,
                                Number(event.target.value || item.quantity),
                                item.unitPrice,
                              )
                            }
                            onChange={(event) => {
                              const next = Number(event.target.value || 1);
                              setSale((current) =>
                                current
                                  ? {
                                      ...current,
                                      items: current.items.map((line) =>
                                        line.id === item.id
                                          ? {
                                              ...line,
                                              quantity: next,
                                              lineTotal: next * line.unitPrice,
                                            }
                                          : line,
                                      ),
                                    }
                                  : current,
                              );
                            }}
                            className="h-8 w-20"
                          />
                        </td>
                        <td className="px-3 py-2">
                          {formatMoney(item.unitPrice)}
                        </td>
                        <td className="px-3 py-2 font-semibold">
                          {formatMoney(item.lineTotal)}
                        </td>
                        <td className="px-3 py-2 text-right">
                          <Button
                            variant="ghost"
                            size="icon-sm"
                            disabled={sale.status === "PAID" || Boolean(busy)}
                            onClick={() => handleRemoveItem(item.id)}
                            aria-label="Remove item"
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="rounded-xl border border-dashed bg-surface-2 p-6 text-center text-sm text-muted-foreground">
                No drugs in the sale yet.
              </div>
            )}

            <Textarea
              value={notes}
              onChange={(event) => setNotes(event.target.value)}
              disabled={Boolean(sale)}
              placeholder="Optional sale notes"
              className="min-h-20"
            />

            <div className="grid gap-3 sm:grid-cols-3">
              <div className="rounded-xl border bg-surface-2 p-3">
                <p className="text-xs text-muted-foreground">Subtotal</p>
                <p className="text-lg font-bold">
                  {formatMoney(sale?.subtotal ?? optimisticSubtotal)}
                </p>
              </div>
              <div className="rounded-xl border bg-surface-2 p-3">
                <p className="text-xs text-muted-foreground">Paid</p>
                <p className="text-lg font-bold">
                  {formatMoney(sale?.paidAmount ?? 0)}
                </p>
              </div>
              <div className="rounded-xl border bg-surface-2 p-3">
                <p className="text-xs text-muted-foreground">Balance</p>
                <p className="text-lg font-bold">
                  {formatMoney(sale?.balanceAmount ?? totalDue)}
                </p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="rounded-2xl border bg-card shadow-sm">
          <CardHeader>
            <CardTitle>Payment and completion</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              <div className="rounded-xl border bg-cyan-50 p-3">
                <p className="text-xs text-module">Total due</p>
                <p className="text-xl font-bold text-foreground">
                  {formatMoney(totalDue)}
                </p>
              </div>
              <div className="rounded-xl border bg-surface-2 p-3">
                <p className="text-xs text-muted-foreground">Payment preview</p>
                <p className="text-xl font-bold">
                  {formatMoney(paymentPreview.amount)}
                </p>
                <p className="text-xs text-muted-foreground">
                  Balance {formatMoney(paymentPreview.balance)}
                </p>
              </div>
            </div>

            <div className="space-y-3">
              {paymentRows.map((row, index) => (
                <div key={row.localId} className="rounded-xl border p-3">
                  <div className="flex items-center justify-between gap-2">
                    <p className="text-sm font-semibold">Payment {index + 1}</p>
                    {paymentRows.length > 1 ? (
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        onClick={() =>
                          setPaymentRows((rows) =>
                            rows.filter((item) => item.localId !== row.localId),
                          )
                        }
                        aria-label="Remove payment line"
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    ) : null}
                  </div>

                  <div className="mt-3 grid gap-3">
                    <select
                      value={row.paymentMethod}
                      onChange={(event) =>
                        updatePaymentRow(row.localId, {
                          paymentMethod: event.target.value as OtcPaymentMethod,
                          insuranceClaimStatus:
                            event.target.value === "INSURANCE"
                              ? "DRAFT"
                              : undefined,
                        })
                      }
                      className="h-10 rounded-lg border bg-card px-3 text-sm"
                    >
                      {PAYMENT_METHODS.map((method) => (
                        <option key={method.value} value={method.value}>
                          {method.label}
                        </option>
                      ))}
                    </select>

                    {row.paymentMethod === "INSURANCE" ? (
                      <div className="grid gap-3">
                        <Input
                          placeholder="Insurance provider"
                          value={row.insuranceProviderName ?? ""}
                          onChange={(event) =>
                            updatePaymentRow(row.localId, {
                              insuranceProviderName: event.target.value,
                            })
                          }
                          className="h-10"
                        />
                        <div className="grid gap-3 sm:grid-cols-2">
                          <Input
                            placeholder="Scheme name"
                            value={row.insuranceSchemeName ?? ""}
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                insuranceSchemeName: event.target.value,
                              })
                            }
                            className="h-10"
                          />
                          <Input
                            placeholder="Member number"
                            value={row.insuranceMemberNumber ?? ""}
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                insuranceMemberNumber: event.target.value,
                              })
                            }
                            className="h-10"
                          />
                          <Input
                            placeholder="Authorization/reference"
                            value={
                              row.authorizationNumber ??
                              row.insuranceClaimReference ??
                              ""
                            }
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                authorizationNumber: event.target.value,
                                insuranceClaimReference: event.target.value,
                              })
                            }
                            className="h-10"
                          />
                          <select
                            value={row.insuranceClaimStatus ?? "DRAFT"}
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                insuranceClaimStatus:
                                  event.target.value as InsuranceClaimStatus,
                              })
                            }
                            className="h-10 rounded-lg border bg-card px-3 text-sm"
                          >
                            {CLAIM_STATUSES.map((status) => (
                              <option key={status} value={status}>
                                {status.replace(/_/g, " ")}
                              </option>
                            ))}
                          </select>
                          <Input
                            type="number"
                            min={0}
                            placeholder="Covered amount"
                            value={row.insuranceCoveredAmount ?? ""}
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                insuranceCoveredAmount: Number(
                                  event.target.value || 0,
                                ),
                                amount: Number(event.target.value || 0),
                              })
                            }
                            className="h-10"
                          />
                          <Input
                            type="number"
                            min={0}
                            placeholder="Patient co-pay"
                            value={row.patientCoPayAmount ?? ""}
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                patientCoPayAmount: Number(
                                  event.target.value || 0,
                                ),
                              })
                            }
                            className="h-10"
                          />
                        </div>
                      </div>
                    ) : (
                      <div className="grid gap-3 sm:grid-cols-2">
                        <Input
                          type="number"
                          min={0}
                          placeholder="Amount"
                          value={row.amount ?? ""}
                          onChange={(event) =>
                            updatePaymentRow(row.localId, {
                              amount: Number(event.target.value || 0),
                            })
                          }
                          className="h-10"
                        />
                        {row.paymentMethod !== "CASH" ? (
                          <Input
                            placeholder={
                              row.paymentMethod === "MPESA_STK"
                                ? "Phone number"
                                : "Transaction/reference"
                            }
                            value={
                              row.paymentMethod === "MPESA_STK"
                                ? row.phoneNumber ?? ""
                                : row.transactionRef ?? row.mpesaReceiptNumber ?? ""
                            }
                            onChange={(event) =>
                              updatePaymentRow(row.localId, {
                                phoneNumber:
                                  row.paymentMethod === "MPESA_STK"
                                    ? event.target.value
                                    : row.phoneNumber,
                                transactionRef:
                                  row.paymentMethod !== "MPESA_STK"
                                    ? event.target.value
                                    : row.transactionRef,
                                mpesaReceiptNumber:
                                  row.paymentMethod === "MPESA_MANUAL"
                                    ? event.target.value
                                    : row.mpesaReceiptNumber,
                              })
                            }
                            className="h-10"
                          />
                        ) : null}
                      </div>
                    )}
                  </div>
                </div>
              ))}
            </div>

            <div className="grid gap-2 sm:grid-cols-2">
              <Button
                type="button"
                variant="outline"
                onClick={() =>
                  setPaymentRows((rows) => [...rows, newPaymentDraft("CASH")])
                }
              >
                <Plus className="h-4 w-4" />
                Add payment line
              </Button>
              <Button
                type="button"
                onClick={handleRecordPayment}
                disabled={!sale || Boolean(busy) || sale.status === "PAID"}
              >
                {busy === "payment" ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <CreditCard className="h-4 w-4" />
                )}
                Record payment
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={handleComplete}
                disabled={
                  !sale ||
                  Boolean(busy) ||
                  sale.status === "PAID" ||
                  sale.paymentStatus !== "PAID"
                }
              >
                <CheckCircle2 className="h-4 w-4" />
                Complete sale
              </Button>
              <Button
                type="button"
                onClick={handlePayAndComplete}
                disabled={!sale || Boolean(busy) || sale.status === "PAID"}
              >
                {busy === "complete" ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Banknote className="h-4 w-4" />
                )}
                Pay and complete
              </Button>
            </div>

            <div className="rounded-xl border bg-surface-2 p-3">
              <div className="flex items-start gap-2">
                <ShieldCheck className="mt-0.5 h-4 w-4 text-module" />
                <div className="text-xs text-muted-foreground">
                  Backend decides final payment state. Stock deducts only after
                  the backend confirms the sale is fully paid and completed.
                </div>
              </div>
            </div>

            <div className="rounded-xl border p-3">
              <p className="text-sm font-semibold">Receipt actions</p>
              <p className="mt-1 text-xs text-muted-foreground">
                Receipt PDFs are server-generated. Pending insurance receipts
                remain marked as pending.
              </p>
              <div className="mt-3 grid gap-2 sm:grid-cols-2">
                <Button
                  variant="outline"
                  disabled={!saleCanShowReceipt(sale) || Boolean(busy)}
                  onClick={() =>
                    sale && downloadOtcReceiptPdf(sale.id, sale.saleNumber)
                  }
                >
                  <Printer className="h-4 w-4" />
                  Download receipt
                </Button>
                <Button
                  variant="outline"
                  disabled={!saleCanShowReceipt(sale)}
                  asChild={Boolean(saleCanShowReceipt(sale))}
                >
                  {saleCanShowReceipt(sale) && sale ? (
                    <Link href={`/print/otc-receipt/${sale.id}`}>
                      <Printer className="h-4 w-4" />
                      Open print route
                    </Link>
                  ) : (
                    <span>
                      <Printer className="h-4 w-4" />
                      Open print route
                    </span>
                  )}
                </Button>
              </div>
            </div>

            <Button type="button" variant="outline" onClick={resetSale}>
              <RefreshCw className="h-4 w-4" />
              New sale / reset
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

