  const [rubberStampUrl, setRubberStampUrl] = React.useState("");
  const [message, setMessage] = React.useState<{ type: "success" | "error"; text: string } | null>(null);

  // ΓöÇΓöÇ List state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [searchClaims, setSearchClaims] = React.useState("");
  const [statusFilter, setStatusFilter] = React.useState("ALL");
  const [detailClaim, setDetailClaim] = React.useState<ClaimRecord | null>(null);

  // ΓöÇΓöÇ Derived ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const patientMatches = React.useMemo(() => {
    const q = patientQuery.trim().toLowerCase();
    if (!q) return patients.slice(0, 12);
    return patients.filter((p) =>
      [p.patientNumber, p.firstName, p.middleName, p.lastName, p.phonePrimary]
        .filter(Boolean).join(" ").toLowerCase().includes(q)
    ).slice(0, 12);
  }, [patientQuery, patients]);

  const selectedPatient = patients.find((p) => String(p.id) === selectedPatientId);
  const patientInvoices = invoices.filter((inv) => String(inv.patientId) === selectedPatientId);
  const selectedInvoice = invoices.find((inv) => String(inv.id) === selectedInvoiceId);
  const diagnosisMatches = searchDiagnoses(diagnosisQuery);

  const filteredClaims = React.useMemo(() => {
    let list = claims;
    if (statusFilter !== "ALL") list = list.filter((c) => c.statusCode === statusFilter);
    if (searchClaims.trim()) {
      const q = searchClaims.trim().toLowerCase();
      list = list.filter((c) =>
        [c.claimNumber, patientName(c.patient), c.patient?.patientNumber, c.diagnosisCode, c.memberNumber]
          .filter(Boolean).join(" ").toLowerCase().includes(q)
      );
    }
    return list;
  }, [claims, statusFilter, searchClaims]);

  // Status count breakdown
  const statusCounts = React.useMemo(() =>
    claims.reduce((acc, c) => { acc[c.statusCode] = (acc[c.statusCode] ?? 0) + 1; return acc; }, {} as Record<string, number>),
    [claims]
  );

  // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const handleCreateClaim = async () => {
    const patient = selectedPatient as typeof patients[0] & { facilityId: number; branchId?: number };
    if (!patient?.facilityId) {
      setMessage({ type: "error", text: "Choose a patient before creating a claim." });
      return;
    }
    try {
      const created = await createMutation.mutateAsync({
        facilityId: (selectedInvoice as any)?.facilityId ?? patient.facilityId,
        branchId: (selectedInvoice as any)?.branchId ?? (patient as any)?.branchId ?? undefined,
        patientId: patient.id,
        invoiceId: selectedInvoice?.id,
        memberNumber: memberNumber.trim() || undefined,
        diagnosisCode: diagnosisCode || undefined,
        diagnosisText: diagnosisText || undefined,
        claimedAmount: claimedAmount ? Number(claimedAmount) : (selectedInvoice as any)?.totalAmount,
        notes: notes.trim() || undefined,
        patientSignatureUrl: patientSignatureUrl || undefined,
        facilitySignatureUrl: facilitySignatureUrl || undefined,
        rubberStampUrl: rubberStampUrl || undefined,
      });
      setMessage({ type: "success", text: `SHA Claim ${created.claimNumber} created successfully.` });
      setSelectedInvoiceId(""); setClaimedAmount(""); setNotes("");
      setPatientSignatureUrl(""); setFacilitySignatureUrl(""); setRubberStampUrl("");
      setDiagnosisCode(""); setDiagnosisText(""); setDiagnosisQuery(""); setMemberNumber("");
    } catch (e: any) {
      setMessage({ type: "error", text: e?.message ?? "Failed to create claim." });
    }
  };

  const handleStatusChange = async (id: number, statusCode: string) => {
    await updateMutation.mutateAsync({ id, payload: { statusCode } });
    if (detailClaim?.id === id) {
      setDetailClaim((c) => c ? { ...c, statusCode } : null);
    }
  };

  const handleAmountSave = async (id: number, amounts: Record<string, number>) => {
    await updateMutation.mutateAsync({ id, payload: amounts });
    setMessage({ type: "success", text: "Claim amounts updated." });
  };

  const handleEligibilityVerified = (result: EligibilityResult) => {
    if (result.memberNumber) setMemberNumber(result.memberNumber);
  };

  return (
    <div className="space-y-6 pb-12">

      {/* ΓöÇΓöÇ Header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <section className="relative overflow-hidden rounded-[2rem] border surface-spotlight shadow-md p-6 md:p-8">
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-blue-800/10 via-indigo-700/5 to-transparent" />
        <div className="pointer-events-none absolute -right-20 -top-20 h-60 w-60 rounded-full bg-blue-400/10 blur-3xl" />

        <div className="relative space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Badge className="rounded-full border-0 bg-primary/10 px-3 py-1 text-xs font-semibold">
                Social Health Authority ΓÇö Kenya
              </Badge>
              <h1 className="mt-3 text-3xl font-bold tracking-tight">SHA Claims Management</h1>
              <p className="mt-1 text-sm text-muted-foreground">
                Generate ┬╖ Validate ┬╖ Submit ┬╖ Track ┬╖ Reconcile ΓÇö Full SHA/DHA claim lifecycle
              </p>
            </div>
            <a href="/templates/claim-form-shif.docx" download>
              <Button variant="outline" size="sm" className="gap-2 rounded-xl">
                <Download className="h-4 w-4" /> SHIF Template
              </Button>
            </a>
          </div>

          {/* Workflow pipeline */}
          <WorkflowBanner currentStep="claim" />
        </div>
      </section>

      {/* ΓöÇΓöÇ Notification banner ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {message && (
        <div className={cn(
          "flex items-center justify-between rounded-2xl border px-5 py-4",
          message.type === "success"
            ? "border-emerald-500/25 bg-emerald-500/8 text-emerald-300"
            : "border-red-500/25 bg-red-500/8 text-red-300"
        )}>
          <div className="flex items-center gap-2 text-sm">
            {message.type === "success" ? <CheckCircle2 className="h-4 w-4 shrink-0" /> : <XCircle className="h-4 w-4 shrink-0" />}
            {message.text}
          </div>
          <button type="button" onClick={() => setMessage(null)}>
            <X className="h-4 w-4" />
          </button>
        </div>
      )}

      {/* ΓöÇΓöÇ Summary KPIs ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-7">
        {[
          { label: "Total Claims", value: String(summary?.count ?? 0), accent: false },
          { label: "Claimed", value: formatMoney(summary?.claimedAmount), accent: false },
          { label: "Covered", value: formatMoney(summary?.coveredAmount), accent: false },
          { label: "Approved", value: formatMoney(summary?.approvedAmount), accent: true },
          { label: "Paid", value: formatMoney(summary?.paidAmount), accent: true },
          { label: "Rejected", value: formatMoney(summary?.rejectedAmount), accent: false },
          { label: "Outstanding", value: formatMoney(summary?.outstandingAmount), accent: false },
        ].map(({ label, value, accent }) => (
          <div key={label} className={cn(
            "rounded-2xl border p-4",
            accent ? "border-emerald-500/20 bg-emerald-500/5" : "border-white/10 bg-white/[0.03]"
          )}>
            <p className="text-[11px] uppercase tracking-widest text-muted-foreground">{label}</p>
            <p className={cn("mt-1.5 text-lg font-bold", accent ? "text-emerald-400" : "text-foreground")}>
              {value}
            </p>
          </div>
        ))}
      </div>

      {/* ΓöÇΓöÇ Main 2-col layout ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="grid gap-6 xl:grid-cols-[400px_1fr]">

        {/* Left: Create new claim */}
        <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
          <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-primary to-indigo-500" />
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <PlusCircle className="h-5 w-5 text-primary" /> New SHA Claim
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">

            {/* Eligibility check */}
            <InlineEligibilityCheck onVerified={handleEligibilityVerified} />

            {/* Patient search */}
            <div>
              <label className="mb-1.5 block text-sm font-medium">Patient *</label>
              <div className="relative mb-2">
                <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  value={patientQuery}
                  onChange={(e) => setPatientQuery(e.target.value)}
                  className="h-10 rounded-2xl pl-10 text-sm"
                  placeholder="Search by name or patient number"
                />
              </div>
              <select
                value={selectedPatientId}
                onChange={(e) => { setSelectedPatientId(e.target.value); setSelectedInvoiceId(""); }}
                className="h-10 w-full rounded-2xl border border-input bg-background px-3 text-sm"
              >
                <option value="">ΓÇö Choose patient ΓÇö</option>
                {patientMatches.map((p) => (
                  <option key={p.id} value={String(p.id)}>
                    {p.patientNumber} / {patientName(p)}
                  </option>
                ))}
              </select>
            </div>

            {/* Invoice */}
            <div>
              <label className="mb-1.5 block text-sm font-medium">Linked Invoice</label>
              <select
                value={selectedInvoiceId}
                onChange={(e) => {
                  const inv = invoices.find((i) => String(i.id) === e.target.value);
                  setSelectedInvoiceId(e.target.value);
                  if (inv) setClaimedAmount(String((inv as any).totalAmount || 0));
                }}
                disabled={!selectedPatientId}
                className="h-10 w-full rounded-2xl border border-input bg-background px-3 text-sm disabled:opacity-50"
              >
                <option value="">ΓÇö Optional ΓÇö</option>
                {patientInvoices.map((inv) => (
                  <option key={inv.id} value={String(inv.id)}>
                    {(inv as any).invoiceNumber} / {formatMoney((inv as any).totalAmount)}
                  </option>
                ))}
              </select>
            </div>

            {/* Member no + amount */}
            <div className="grid gap-3 sm:grid-cols-2">
              <div>
                <label className="mb-1.5 block text-sm font-medium flex items-center gap-1">
                  <Shield className="h-3.5 w-3.5 text-primary" /> SHA Member No.
                </label>
                <Input
                  value={memberNumber}
                  onChange={(e) => setMemberNumber(e.target.value)}
                  className="h-10 rounded-2xl font-mono text-sm"
                  placeholder="SHA-XXXXXXXX"
                />
              </div>
              <div>
                <label className="mb-1.5 block text-sm font-medium">Claimed Amount (KES)</label>
                <Input
                  type="number"
                  value={claimedAmount}
                  onChange={(e) => setClaimedAmount(e.target.value)}
                  className="h-10 rounded-2xl font-mono text-sm"
                  placeholder="0"
                />
              </div>
            </div>

            {/* Diagnosis */}
            <div>
              <label className="mb-1.5 block text-sm font-medium">Diagnosis (ICD-11)</label>
              <Input
                value={diagnosisQuery}
                onChange={(e) => setDiagnosisQuery(e.target.value)}
                className="h-10 rounded-2xl text-sm"
                placeholder="Type diagnosis or codeΓÇª"
              />
              {diagnosisQuery && diagnosisMatches.length > 0 && (
                <div className="mt-1 max-h-44 overflow-y-auto rounded-2xl border border-border bg-background shadow-lg">
                  {diagnosisMatches.map((d) => (
                    <button
                      key={d.code}
                      type="button"
                      className="block w-full px-4 py-2.5 text-left text-sm hover:bg-accent transition-colors"
                      onClick={() => {
                        setDiagnosisCode(d.code);
                        setDiagnosisText(d.label);
                        setDiagnosisQuery(`${d.code} ΓÇö ${d.label}`);
                      }}
                    >
                      <span className="font-mono font-semibold text-primary">{d.code}</span>
                      <span className="text-muted-foreground ml-2">{d.label}</span>
                    </button>
                  ))}
                </div>
              )}
              {diagnosisCode && (
                <p className="mt-1 text-xs text-muted-foreground font-mono">Selected: {diagnosisCode}</p>
              )}
            </div>

            {/* Notes */}
            <div>
              <label className="mb-1.5 block text-sm font-medium">Notes / Authorization Ref</label>
              <Textarea
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="min-h-[80px] rounded-2xl text-sm"
                placeholder="Authorization codes, pre-approval references, remarksΓÇª"
              />
            </div>

            {/* Signatures */}
            <div className="grid gap-3 sm:grid-cols-3">
              {([
                ["Patient Signature", patientSignatureUrl, setPatientSignatureUrl],
                ["Facility Signature", facilitySignatureUrl, setFacilitySignatureUrl],
                ["Rubber Stamp", rubberStampUrl, setRubberStampUrl],
              ] as [string, string, React.Dispatch<React.SetStateAction<string>>][]).map(([label, value, setter]) => (
                <label key={label} className="space-y-1 text-xs">
                  <span className="font-medium text-muted-foreground">{label}</span>
                  <Input
                    type="file"
                    accept="image/*"
                    className="h-9 rounded-xl text-xs"
                    onChange={async (e) => {
                      const url = await readImageAsDataUrl(e.target.files?.[0]);
                      setter(url);
                    }}
                  />
                  {value && (
                    // eslint-disable-next-line @next/next/no-img-element
                    <img src={value} alt="" className="h-12 w-full rounded-xl border border-border object-contain" />
                  )}
                </label>
              ))}
            </div>

            <Button
              type="button"
              className="h-12 w-full rounded-2xl gap-2"
              onClick={handleCreateClaim}
              disabled={createMutation.isPending || !selectedPatientId}
            >
              {createMutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <FileCheck2 className="h-4 w-4" />
              )}
              Generate SHA Claim
            </Button>
          </CardContent>
        </Card>

        {/* Right: Claims tracker */}
        <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
          <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-amber-500 to-orange-500" />
          <CardHeader>
            <div className="flex items-center justify-between gap-3 flex-wrap">
              <CardTitle className="flex items-center gap-2 text-base">
                <FileText className="h-5 w-5 text-amber-400" /> Claim Tracker
                <span className="text-xs font-normal text-muted-foreground">({filteredClaims.length} claims)</span>
              </CardTitle>
              <div className="flex gap-2">
                <div className="relative">
                  <Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    value={searchClaims}
                    onChange={(e) => setSearchClaims(e.target.value)}
                    placeholder="Search claimsΓÇª"
                    className="h-9 w-44 rounded-xl pl-8 text-xs"
                  />
                </div>
              </div>
            </div>

            {/* Status filter tabs */}
            <div className="flex gap-1 overflow-x-auto pb-1 mt-2">
              {[
                { id: "ALL", label: `All (${claims.length})` },
                ...Object.keys(STATUS_CONFIG)
                  .filter((s) => (statusCounts[s] ?? 0) > 0)
                  .map((s) => ({ id: s, label: `${STATUS_CONFIG[s].label} (${statusCounts[s]})` })),
              ].map((tab) => (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => setStatusFilter(tab.id)}
                  className={cn(
                    "shrink-0 rounded-xl px-3 py-1.5 text-[11px] font-medium transition-all",
                    statusFilter === tab.id
                      ? "bg-primary text-primary-foreground shadow-sm"
                      : "bg-white/[0.03] text-muted-foreground border border-white/10 hover:text-foreground"
                  )}
                >
                  {tab.label}
                </button>
              ))}
            </div>
          </CardHeader>

          <CardContent>
            {filteredClaims.length === 0 ? (
              <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
                <div className="flex h-16 w-16 items-center justify-center rounded-3xl bg-primary/10">
                  <FileCheck2 className="h-8 w-8 text-primary" />
                </div>
                <div>
                  <p className="font-semibold">No claims found</p>
                  <p className="mt-1 text-sm text-muted-foreground">
                    {searchClaims || statusFilter !== "ALL"
                      ? "Try adjusting your filters."
                      : "Create your first SHA claim using the form on the left."}
                  </p>
                </div>
              </div>
            ) : (
              <div className="space-y-2 max-h-[640px] overflow-y-auto pr-1">
                {filteredClaims.map((claim) => {
                  const cfg = STATUS_CONFIG[claim.statusCode] ?? STATUS_CONFIG["DRAFT"];
                  return (
                    <div
                      key={claim.id}
                      className="group flex items-center gap-4 rounded-2xl border border-border/50 bg-background/40 px-4 py-3 transition-all hover:border-primary/30 hover:bg-background/60"
                    >
                      {/* Status dot */}
                      <span className={cn("h-2.5 w-2.5 shrink-0 rounded-full", cfg.dot)} />

                      {/* Core info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-mono text-sm font-semibold">{claim.claimNumber}</span>
                          <ClaimStatusBadge status={claim.statusCode} />
                          {claim.fidCode && (
                            <span className="text-[10px] text-muted-foreground font-mono border border-border/40 rounded px-1.5 py-0.5 bg-background/60">
                              FID: {claim.fidCode}
                            </span>
                          )}
                        </div>
                        <div className="mt-0.5 flex items-center gap-3 text-xs text-muted-foreground flex-wrap">
                          <span>{patientName(claim.patient)}</span>
                          {claim.diagnosisCode && (
                            <span className="font-mono">{claim.diagnosisCode}</span>
                          )}
                          <span>{relativeTime(claim.createdAt)}</span>
                        </div>
                      </div>

                      {/* Amounts */}
                      <div className="hidden md:flex flex-col items-end gap-0.5 shrink-0 min-w-[100px]">
                        <span className="text-sm font-semibold">{formatMoney(claim.claimedAmount)}</span>
                        {claim.paidAmount > 0 && (
                          <span className="text-xs text-emerald-400">{formatMoney(claim.paidAmount)} paid</span>
                        )}
                        {claim.rejectedAmount > 0 && (
                          <span className="text-xs text-red-400">{formatMoney(claim.rejectedAmount)} rejected</span>
                        )}
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-2 shrink-0">
                        {claim.statusCode === "DRAFT" && (
                          <Button
                            type="button"
                            size="sm"
                            variant="outline"
                            className="h-8 rounded-xl gap-1.5 text-xs"
                            onClick={() => handleStatusChange(claim.id, "SUBMITTED")}
                            disabled={updateMutation.isPending}
                          >
                            <Send className="h-3 w-3" /> Submit
                          </Button>
                        )}
                        <button
                          type="button"
                          onClick={() => setDetailClaim(claim)}
                          className="rounded-xl border border-border/50 p-2 text-muted-foreground hover:text-foreground hover:border-primary/40 transition-colors"
                          title="View details"
                        >
                          <Eye className="h-3.5 w-3.5" />
                        </button>
                        <button
                          type="button"
                          onClick={() => downloadShaClaimPdf(claim.id, claim.claimNumber)}
                          className="rounded-xl border border-border/50 p-2 text-muted-foreground hover:text-foreground hover:border-primary/40 transition-colors"
                          title="Download PDF"
                        >
                          <Download className="h-3.5 w-3.5" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* ΓöÇΓöÇ Detail drawer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {detailClaim && (
        <ClaimDetailDrawer
          claim={detailClaim}
          onClose={() => setDetailClaim(null)}
          onStatusChange={handleStatusChange}
          onAmountSave={handleAmountSave}
          isUpdating={updateMutation.isPending}
        />
      )}
    </div>
  );
}

"use client";


import * as React from "react";
import {
  AlertTriangle,
  CheckCircle2,
  HeartPulse,
  Loader2,
  Play,
  Sparkles,
  Stethoscope,
  Thermometer,
} from "lucide-react";
import { useWaitingTriage } from "@/hooks/use-waiting-triage";
import { useStartTriage } from "@/hooks/use-start-triage";
import { useCompleteTriage } from "@/hooks/use-complete-triage";
import { useClinics } from "@/hooks/use-clinics";
import { useStaff } from "@/hooks/use-staff";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { useScope } from "@/providers/scope-provider";
import { cn } from "@/lib/utils";
import type { TriageItem } from "@/services/triage-service";
import type { ClinicItem } from "@/services/clinic-service";
import type { StaffItem } from "@/services/staff-service";


function patientName(item: TriageItem) {
  const p = item.patient;
  if (!p) return "Unknown patient";
  return [p.firstName, p.middleName, p.lastName].filter(Boolean).join(" ");
}


function TriageStat({
  label,
  value,
}: {
  label: string;
  value: string | number;
}) {
  return (
    <div className="rounded-[1.2rem] border border-white/10 bg-card/[0.03] p-4">
      <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">
        {label}
      </p>
      <p className="mt-2 text-sm font-semibold">{value}</p>
    </div>
  );
}


function getPriorityTone(priority: string) {
  switch (priority.toUpperCase()) {
    case "CRITICAL":
      return "border-red-500/20 bg-red-500/10 text-red-300";
    case "EMERGENCY":
      return "border-orange-500/20 bg-orange-500/10 text-orange-300";
    case "URGENT":
      return "border-amber-500/20 bg-amber-500/10 text-amber-300";
    default:
      return "border-cyan-500/20 bg-cyan-500/10 text-cyan-300";
  }
}


function suggestPriority(params: {
  oxygenSaturation?: number;
  painScore?: number;
  systolicBp?: number;
  diastolicBp?: number;
  pulseRate?: number;
  temperatureC?: number;
}) {
  const {
    oxygenSaturation,
    painScore,
    systolicBp,
    diastolicBp,
    pulseRate,
    temperatureC,
  } = params;


  if (
    (oxygenSaturation !== undefined && oxygenSaturation < 90) ||
    (systolicBp !== undefined && systolicBp < 80) ||
    (pulseRate !== undefined && pulseRate > 140)
  ) {
    return "CRITICAL";
  }


  if (
    (painScore !== undefined && painScore >= 8) ||
    (temperatureC !== undefined && temperatureC >= 39.5) ||
    (systolicBp !== undefined && systolicBp >= 180) ||
    (diastolicBp !== undefined && diastolicBp >= 120)
  ) {
    return "EMERGENCY";
  }


  if (
    (painScore !== undefined && painScore >= 5) ||
    (oxygenSaturation !== undefined && oxygenSaturation < 94) ||
    (pulseRate !== undefined && pulseRate > 110)
  ) {
    return "URGENT";
  }


  return "NORMAL";
}


export default function TriagePage() {
  const { facilityId, facilityName, selectedBranchId, selectedBranchName } = useScope();
  const { data, isLoading } = useWaitingTriage();
  const { data: clinicsData } = useClinics();
  const { data: staffData } = useStaff();


  const startTriageMutation = useStartTriage();
  const completeTriageMutation = useCompleteTriage();


  const queue = Array.isArray(data) ? data : [];
  const clinics = Array.isArray(clinicsData) ? (clinicsData as ClinicItem[]) : [];
  const staffItems = Array.isArray(staffData) ? (staffData as StaffItem[]) : [];


  const [selectedId, setSelectedId] = React.useState<number | null>(null);


  const selected = React.useMemo(
    () => queue.find((item) => item.id === selectedId) ?? queue[0] ?? null,
    [queue, selectedId],
  );


  React.useEffect(() => {
    if (!selectedId && queue.length > 0) {
      setSelectedId(queue[0].id);
    }
  }, [queue, selectedId]);


  const filteredClinics = React.useMemo(() => {
    return clinics.filter((clinic) => {
      if (facilityId && clinic.facilityId !== facilityId) return false;
      if (!selectedBranchId) return true;
      return !clinic.branchId || clinic.branchId === selectedBranchId;
    });
  }, [clinics, facilityId, selectedBranchId]);


  const doctors = React.useMemo(() => {
    return staffItems.filter((item) => {
      if (!item.isClinician || !item.isActive) return false;
      if (facilityId && item.facilityId !== facilityId) return false;
      if (!selectedBranchId) return true;
      return !item.branchId || item.branchId === selectedBranchId;
    });
  }, [staffItems, facilityId, selectedBranchId]);


  const [temperatureC, setTemperatureC] = React.useState("");
  const [systolicBp, setSystolicBp] = React.useState("");
  const [diastolicBp, setDiastolicBp] = React.useState("");
  const [pulseRate, setPulseRate] = React.useState("");
  const [respiratoryRate, setRespiratoryRate] = React.useState("");
  const [oxygenSaturation, setOxygenSaturation] = React.useState("");
  const [weightKg, setWeightKg] = React.useState("");
  const [heightCm, setHeightCm] = React.useState("");
  const [painScore, setPainScore] = React.useState("");
  const [triagePriority, setTriagePriority] = React.useState("NORMAL");
  const [notes, setNotes] = React.useState("");
  const [chiefComplaint, setChiefComplaint] = React.useState("");
  const [clinicId, setClinicId] = React.useState("");
  const [routedDoctorId, setRoutedDoctorId] = React.useState("");
  const [priorityTouched, setPriorityTouched] = React.useState(false);
  const [message, setMessage] = React.useState<string | null>(null);


  React.useEffect(() => {
    if (!selected) return;
    setTemperatureC(selected.temperatureC?.toString() ?? "");
    setSystolicBp(selected.systolicBp?.toString() ?? "");
    setDiastolicBp(selected.diastolicBp?.toString() ?? "");
    setPulseRate(selected.pulseRate?.toString() ?? "");
    setRespiratoryRate(selected.respiratoryRate?.toString() ?? "");
    setOxygenSaturation(selected.oxygenSaturation?.toString() ?? "");
    setWeightKg(selected.weightKg?.toString() ?? "");
    setHeightCm(selected.heightCm?.toString() ?? "");
    setPainScore(selected.painScore?.toString() ?? "");
    setTriagePriority(selected.triagePriority ?? "NORMAL");
    setNotes(selected.notes ?? "");
    setChiefComplaint(selected.chiefComplaint ?? "");
    setClinicId(selected.clinicId ? String(selected.clinicId) : "");
    setRoutedDoctorId(selected.routedDoctorId ? String(selected.routedDoctorId) : "");
    setPriorityTouched(false);
    setMessage(null);
  }, [selected]);


  const suggestedPriority = React.useMemo(() => {
    return suggestPriority({
      oxygenSaturation: oxygenSaturation ? Number(oxygenSaturation) : undefined,
      painScore: painScore ? Number(painScore) : undefined,
      systolicBp: systolicBp ? Number(systolicBp) : undefined,
      diastolicBp: diastolicBp ? Number(diastolicBp) : undefined,
      pulseRate: pulseRate ? Number(pulseRate) : undefined,
      temperatureC: temperatureC ? Number(temperatureC) : undefined,
    });
  }, [
    oxygenSaturation,
    painScore,
    systolicBp,
    diastolicBp,
    pulseRate,
    temperatureC,
  ]);


  React.useEffect(() => {
    if (!priorityTouched) {
      setTriagePriority(suggestedPriority);
    }
  }, [suggestedPriority, priorityTouched]);


  const handleStart = async () => {
    if (!selected) return;
    setMessage(null);
    await startTriageMutation.mutateAsync(selected.id);
  };


  const handleComplete = async () => {
    if (!selected) return;
    setMessage(null);


    const result = await completeTriageMutation.mutateAsync({
      id: selected.id,
      payload: {
        chiefComplaint: chiefComplaint || undefined,
        temperatureC: temperatureC ? Number(temperatureC) : undefined,
        systolicBp: systolicBp ? Number(systolicBp) : undefined,
        diastolicBp: diastolicBp ? Number(diastolicBp) : undefined,
        pulseRate: pulseRate ? Number(pulseRate) : undefined,
        respiratoryRate: respiratoryRate ? Number(respiratoryRate) : undefined,
        oxygenSaturation: oxygenSaturation ? Number(oxygenSaturation) : undefined,
        weightKg: weightKg ? Number(weightKg) : undefined,
        heightCm: heightCm ? Number(heightCm) : undefined,
        painScore: painScore ? Number(painScore) : undefined,
        triagePriority,
        notes: notes || undefined,
        clinicId: clinicId ? Number(clinicId) : undefined,
        routedDoctorId: routedDoctorId ? Number(routedDoctorId) : undefined,
        statusCode: "READY_FOR_DOCTOR",
      },
    });


    setMessage(
      `Triage completed. Patient sent to doctor queue.${result.appointmentId ? ` Appointment ID: ${result.appointmentId}` : ""}`,
    );
  };


  return (
    <div className="space-y-6">
      <section className="relative overflow-hidden rounded-[2rem] border surface-spotlight shadow-md p-6 md:p-8">
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-blue-600/10 via-cyan-500/5 to-transparent" />
        <div className="pointer-events-none absolute -right-24 -top-24 h-64 w-64 rounded-full bg-cyan-400/10 blur-3xl" />
        <div className="pointer-events-none absolute -left-16 bottom-0 h-52 w-52 rounded-full bg-blue-500/10 blur-3xl" />


        <div className="relative flex flex-col gap-5 xl:flex-row xl:items-end xl:justify-between">
          <div className="space-y-3">
            <Badge className="rounded-full border-0 bg-cyan-600/10 px-3 py-1 text-module">
              Triage Station
            </Badge>


            <div className="flex items-center gap-3">
              <div className="flex h-14 w-14 items-center justify-center rounded-3xl bg-primary/10">
                <HeartPulse className="h-7 w-7 text-primary" />
              </div>


              <div>
                <h1 className="text-3xl font-bold tracking-tight md:text-4xl">
                  Triage Queue
                </h1>
                <p className="text-muted-foreground">
                  Assess patients, capture vitals, assign urgency, and route them forward
                </p>
              </div>
            </div>
          </div>


          <div className="grid gap-3 sm:grid-cols-3 xl:w-[560px]">
            <TriageStat label="Facility" value={facilityName || "No facility"} />
            <TriageStat label="Branch" value={selectedBranchName || "No branch"} />
            <TriageStat label="Waiting Cases" value={String(queue.length)} />
          </div>
        </div>
      </section>


      {message ? (
        <div className="rounded-[1.4rem] border border-cyan-500/20 bg-cyan-500/8 px-4 py-4 text-sm text-cyan-300">
          {message}
        </div>
      ) : null}


      <section className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
        <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
          <CardHeader>
            <CardTitle className="text-lg">Waiting Patients</CardTitle>
          </CardHeader>


          <CardContent className="space-y-3">
            {isLoading ? (
              Array.from({ length: 5 }).map((_, index) => (
                <div
                  key={index}
                  className="rounded-[1.3rem] border border-white/10 bg-card/[0.03] p-4"
                >
                  <div className="h-5 w-40 rounded bg-card/10" />
                  <div className="mt-3 h-4 w-56 rounded bg-card/10" />
                </div>
              ))
            ) : queue.length === 0 ? (
              <div className="rounded-[1.3rem] border border-dashed border-white/10 bg-card/[0.02] p-5 text-sm text-muted-foreground">
                No patients are currently waiting for triage.
              </div>
            ) : (
              queue.map((item) => {
                const active = selected?.id === item.id;


                return (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => setSelectedId(item.id)}
                    className={cn(
                      "w-full rounded-[1.3rem] border p-4 text-left transition-all",
                      active
                        ? "border-cyan-400/40 bg-cyan-500/10"
                        : "border-white/10 bg-card/[0.03] hover:bg-card/[0.05]",
                    )}
                  >
                    <div className="flex items-start justify-between gap-4">
                      <div className="min-w-0">
                        <p className="truncate font-semibold">{patientName(item)}</p>
                        <p className="mt-1 text-sm text-muted-foreground">
                          {item.patient?.patientNumber || item.triageNumber}
                        </p>
                        <p className="mt-2 text-sm text-muted-foreground">
                          {item.chiefComplaint || "No complaint recorded yet"}
                        </p>
                      </div>


                      {active ? (
                        <CheckCircle2 className="h-5 w-5 shrink-0 text-cyan-400" />
                      ) : null}
                    </div>
                  </button>
                );
              })
            )}
          </CardContent>
        </Card>


        <Card className="relative overflow-hidden rounded-[1.8rem] surface-spotlight shadow-md">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-lg">Triage Assessment</CardTitle>


            <div className="flex gap-2">
              <Button
                type="button"
                variant="outline"
                className="rounded-2xl"
                disabled={!selected || startTriageMutation.isPending}
                onClick={handleStart}
              >
                {startTriageMutation.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Play className="mr-2 h-4 w-4" />
                )}
                Start
              </Button>


              <Button
                type="button"
                className="rounded-2xl"
                disabled={!selected || completeTriageMutation.isPending}
                onClick={handleComplete}
              >
                {completeTriageMutation.isPending ? (
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                ) : (
                  <Stethoscope className="mr-2 h-4 w-4" />
                )}
                Complete
              </Button>
            </div>
          </CardHeader>


          <CardContent className="space-y-5">
            {!selected ? (
              <div className="rounded-[1.3rem] border border-dashed border-white/10 bg-card/[0.02] p-5 text-sm text-muted-foreground">
                Select a patient from the waiting queue.
              </div>
            ) : (
              <>
                <div className="rounded-[1.3rem] border border-white/10 bg-card/[0.03] p-4">
                  <p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">
                    Current Patient
                  </p>
                  <p className="mt-2 text-lg font-bold">{patientName(selected)}</p>
                  <p className="mt-1 text-sm text-muted-foreground">
                    {selected.patient?.patientNumber || selected.triageNumber}
                  </p>
                </div>


                <div className="rounded-[1.3rem] border border-white/10 bg-card/[0.03] p-4">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex items-center gap-2">
                      <Sparkles className="h-4 w-4 text-cyan-300" />
                      <p className="text-sm font-medium">System Suggested Priority</p>
                    </div>


                    <span
                      className={cn(
                        "rounded-full border px-3 py-1 text-xs font-semibold",
                        getPriorityTone(suggestedPriority),
                      )}
                    >
                      {suggestedPriority}
                    </span>
                  </div>


                  <p className="mt-3 text-xs text-muted-foreground">
                    Suggested from pain score, oxygen saturation, temperature, pulse, and blood pressure.
                  </p>
                </div>


                <div>
                  <label className="mb-2 block text-sm font-medium">
                    Chief Complaint
                  </label>
                  <Textarea
                    value={chiefComplaint}
                    onChange={(e) => setChiefComplaint(e.target.value)}
                    className="min-h-[90px] rounded-2xl"
                    placeholder="Describe presenting complaint"
                  />
                </div>


                <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
                  <div>
                    <label className="mb-2 block text-sm font-medium">Temperature ┬░C</label>
                    <div className="relative">
                      <Thermometer className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                      <Input
                        value={temperatureC}
                        onChange={(e) => setTemperatureC(e.target.value)}
                        className="h-12 rounded-2xl pl-10"
                      />
                    </div>
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Systolic BP</label>
                    <Input
                      value={systolicBp}
                      onChange={(e) => setSystolicBp(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Diastolic BP</label>
                    <Input
                      value={diastolicBp}
                      onChange={(e) => setDiastolicBp(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Pulse Rate</label>
                    <Input
                      value={pulseRate}
                      onChange={(e) => setPulseRate(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Respiratory Rate</label>
                    <Input
                      value={respiratoryRate}
                      onChange={(e) => setRespiratoryRate(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Oxygen Saturation</label>
                    <Input
                      value={oxygenSaturation}
                      onChange={(e) => setOxygenSaturation(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Weight (kg)</label>
                    <Input
                      value={weightKg}
                      onChange={(e) => setWeightKg(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Height (cm)</label>
                    <Input
                      value={heightCm}
                      onChange={(e) => setHeightCm(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Pain Score (0-10)</label>
                    <Input
                      value={painScore}
                      onChange={(e) => setPainScore(e.target.value)}
                      className="h-12 rounded-2xl"
                    />
                  </div>
                </div>


                <div className="grid gap-4 md:grid-cols-2">
                  <div>
                    <label className="mb-2 block text-sm font-medium">Route to Clinic</label>
                    <select
                      value={clinicId}
                      onChange={(e) => setClinicId(e.target.value)}
                      className="flex h-12 w-full rounded-2xl border border-white/10 bg-background px-4 text-sm"
                    >
                      <option value="">Select clinic</option>
                      {filteredClinics.map((clinic) => (
                        <option key={clinic.id} value={clinic.id}>
                          {clinic.name}
                        </option>
                      ))}
                    </select>
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Route to Doctor</label>
                    <select
                      value={routedDoctorId}
                      onChange={(e) => setRoutedDoctorId(e.target.value)}
                      className="flex h-12 w-full rounded-2xl border border-white/10 bg-background px-4 text-sm"
                    >
                      <option value="">Select doctor</option>
                      {doctors.map((doctor) => (
                        <option key={doctor.id} value={doctor.id}>
                          {[doctor.firstName, doctor.lastName].filter(Boolean).join(" ")}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>


                <div className="grid gap-4 md:grid-cols-2">
                  <div>
                    <label className="mb-2 block text-sm font-medium">Final Triage Priority</label>
                    <select
                      value={triagePriority}
                      onChange={(e) => {
                        setPriorityTouched(true);
                        setTriagePriority(e.target.value);
                      }}
                      className="flex h-12 w-full rounded-2xl border border-white/10 bg-background px-4 text-sm"
                    >
                      <option value="NORMAL">NORMAL</option>
                      <option value="URGENT">URGENT</option>
                      <option value="EMERGENCY">EMERGENCY</option>
                      <option value="CRITICAL">CRITICAL</option>
                    </select>
                  </div>


                  <div>
                    <label className="mb-2 block text-sm font-medium">Status</label>
                    <Input
                      value={selected.statusCode || "WAITING_TRIAGE"}
                      disabled
                      className="h-12 rounded-2xl opacity-80"
                    />
                  </div>
                </div>


                {triagePriority === "CRITICAL" ? (
                  <div className="rounded-[1.3rem] border border-red-500/20 bg-red-500/10 p-4 text-red-300">
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4" />
                      <p className="font-semibold">Critical priority selected</p>
                    </div>
                    <p className="mt-2 text-sm text-red-200/80">
                      This patient will appear at the top of the doctor queue.
                    </p>
                  </div>
                ) : null}


                <div>
                  <label className="mb-2 block text-sm font-medium">Triage Notes</label>
                  <Textarea
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    className="min-h-[110px] rounded-2xl"
                    placeholder="Clinical notes from triage"
                  />
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

'use client';

import { Shield, ShieldAlert, ShieldCheck, Loader2 } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { useState, useEffect } from 'react';

interface PatientEligibilityBadgeProps {
  patientId: string;
}

export function PatientEligibilityBadge({ patientId }: PatientEligibilityBadgeProps) {
